insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('zeaschd-hoda-de-klaane-eitrangld-und-daunn-hodas-oogschleppd', 'Zeaschd hoda de Klaane eitrangld, und daunn hodas oogschleppd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Zuerst hat er die Kleine eingetrankelt, und dann hat er sie abgeschleppt!', '[{"kategorie": "wörtlich", "text": "\"Zuerst hat er die Kleine betrunken gemacht, und dann hat er sie abgeschleppt!\"  2. Zuerst hat er sie warmgetrunken – und dann abgeschleppt wie ein Profi!  3. Zuerst hat er sie charmant auf Pegel gebracht, und dann war sie plötzlich in seinem Taxi!"}]'::jsonb, 'wem eitrangln'),
  ('si-in-oasch-eitunkn', 'si in Oasch eitunkn', '', '', '', '', 'sich den Arsch eintunken', '[{"kategorie": "", "text": "sich selbst schädigen, Schaden erleiden, sich selbst Schaden zufügen"}, {"kategorie": "", "text": "durch eigene Dummheit Schaden erleiden, der Angeschmierte sein, da Gschööde sei"}]'::jsonb, ''),
  ('da-eigane-freind-hod-eam-uandlich-eitunkd', 'Da eigane Freind hod eam uandlich eitunkd!', '', '', '', '', 'Sein eigener Freund hat ihn ordentlich eingetunkt!', '[{"kategorie": "", "text": "Sein eigener Freund hat ihn gehörig reingelassen!  2. Sein eigener Freund hat ihn ordentlich mithineingezogen!"}]'::jsonb, ''),
  ('i-bin-nua-kuaz-eitunkt', 'I bin nua kuaz eitunkt!', '', '', '', '', 'Ich bin nur kurz eingetunkt!', '[{"kategorie": "", "text": "Ich bin nur kurz eingenickt!  2. Ich war nur kurz weggetreten!"}]'::jsonb, ''),
  ('tunk-de-semml-ei-in-soft', 'Tunk de Semml ei in Soft!', '', '', '', '', 'Tunke die Semmel in den Saft ein!', '[{"kategorie": "", "text": "Tauche die Semmel in die Soße!  2. Dippe das Brötchen in die Sauce!"}]'::jsonb, ''),
  ('den-brauchsd-ned-niidaschrein-dea-geed-von-soeoewa-waunnsd-eam-so-richtig-eiwaaksd', 'Den brauchsd ned niidaschrein - dea geed von sööwa, waunnsd eam so richtig eiwaaksd!', '', '', '', 'Wiener Gaunersprache', 'Den brauchst du nicht niederzuschreien – der geht von selber, wenn du ihn so richtig einweichst!', '[{"kategorie": "wörtlich", "text": "\"Den brauchst du nicht anzubrüllen – der geht von selber, wennst du ihn weichkochst!\"  2. Den musst du nicht anschreien – lass ihn einfach im eigenen Saft schmoren, bis er von alleine einknickt!  3. Den musst du nicht anschnauzen – koch ihn weich, dann zerfällt er wie ein Keks in heißer Milch!"}]'::jsonb, ''),
  ('heit-rennan-de-eisbaean-um', 'Heit rennan de Eisbäan um!', '', '', '', '', 'Heute rennen die Eisbären herum!', '[{"kategorie": "", "text": "Heute ist es frostig kalt!  2. Heute herrscht Eiseskälte!"}]'::jsonb, ''),
  ('eisn-rostet-faungeisn-kostet-meistns-an-gaunzn-fuass', 'Eisn rostet, Faungeisn kostet - meistns an gaunzn Fuass!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Eisen rostet, Fangeisen kostet - meistens einen ganzen Fuß!', '[{"kategorie": "wörtlich", "text": "\"Eisen rostet, Fangeisen kostet - meistens ein ganzes Bein!\"  2. Eisen korrodiert, Fangeisen amputiert – meist ein ganzes Bein!  3. Eisen zerfällt, Fangeisen schnellt – und danach fehlt dir ein Haxen!"}]'::jsonb, ''),
  ('a-haass-eisn-a-volla-tank-und-ka-zueue-wos-wueuesd-mea', 'A haass Eisn, a volla Tank und ka Züü - wos wüüsd mea?', '', '', '', 'Wiener Mechaniker-Slang', 'Ein heißes Eisen, ein voller Tank und kein Ziel - was willst du mehr?', '[{"kategorie": "wörtlich", "text": "\"Ein heißer Feuerstuhl, ein voller Tank und kein Ziel - was willst du mehr?\"  2. Chrom unterm Hintern, Benzin im Blut und null Verpflichtung - was willst du mehr?  3. Ein brüllendes Bike, freie Fahrt und keine Pläne - mehr Freiheit geht nicht!"}]'::jsonb, 'A haass Eisn!'),
  ('da-kiiwara-hod-eam-de-eisn-augleegd-no-bevuara-mama-hod-schrein-kenna', 'Da Kiiwara hod eam de Eisn augleegd, no bevuara ''Mama'' hod schrein kenna!', '', '', '', 'Wiener Gaunersprache', 'Der Kieberer hat ihm die Eisen angelegt, noch bevor er ''Mama'' hat schreien können!', '[{"kategorie": "wörtlich", "text": "\"Der Kriminalpolizist hat ihm die Handschellen angelegt, noch bevor er ''Mama'' hat schreien können!\"  2. Der Kriminalbeamte legte ihm die Handschellen an, noch bevor er ein einziges Wort sagen konnte"}, {"kategorie": "", "text": "Der Polizist hat ihm die [[Achter]] angelegt, noch bevor er überhaupt den Mund aufmachen konnte!"}]'::jsonb, 'Eisn auleeng'),
  ('warad-mei-leebm-a-weakzeigkostn-warad-i-des-rostige-eisn-hintn-rechts', 'Warad mei Leebm a Weakzeigkostn, warad I des rostige Eisn hintn rechts!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wär'' mein Leben ein Werkzeugkasten, wär'' ich das rostige Eisen hinten rechts!', '[{"kategorie": "wörtlich", "text": "\"Wär mein Leben ein Werkzeugkasten, wär ich das Ding, von dem keiner mehr weiß, wofür’s mal gut war!\"  2. Wenn mein Leben ''ne Werkzeugkiste wär, wär ich der abgebrochene Schraubenzieher im Eck!  3. Wär'' mei Leb''n a Werkzeugkist''n, warad i des verrostete Eisen unterm Schraubenschlüssel!"}]'::jsonb, ''),
  ('do-schdeen-da-d-eisn-ausse', 'Do schdeen da d''Eisn ausse!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da stehen dir die Eisen raus', '[{"kategorie": "wörtlich", "text": "\"Da stehen dir die Schuheisen raus!\"  2. Da zieht’s dir die Schuhsohlen nach oben!  3. Da fliegen dir die Hufeisen um die Ohren!  4. Da geht einem der Hut hoch!  5. Da platzt einem der Kragen!"}]'::jsonb, ''),
  ('eisn-auleeng', 'Eisn auleeng', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Eisen anlegen', '[{"kategorie": "wörtlich", "text": "\"die Handeisen anlegen\""}, {"kategorie": "", "text": "die Handschellen anlegen"}, {"kategorie": "", "text": "die Handfesseln fixieren"}]'::jsonb, ''),
  ('a-haass-eisn', 'A haass Eisn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ein heißes Eisen!', '[{"kategorie": "wörtlich", "text": "\"Ein heißes Eisen!\" (vom mittelhochdeutschen \"īsen\"=\"Eisen\")"}, {"kategorie": "fig.", "text": "(a) Eine heikle Angelegenheit!  (b) Ein brandheißes Thema!"}, {"kategorie": "Mechanikerjargon", "text": "(a) \"Was für ein heißer Feuerstuhl!\" (schnelles, schickes Motorrad);  (b) \"Ein wahrer Teufelsschlitten!\"  3. \"Was für eine heiße Rakete!\"  4. \"Ein wirklich heißer [[Hobel]]!\""}]'::jsonb, ''),
  ('des-is-a-haass-eisn-do-misch-i-mi-liawa-ned-ei', 'Des is a haass Eisn, do misch I mi liawa ned ei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein heißes Eisen, da misch'' ich mich lieber nicht ein!', '[{"kategorie": "wörtlich", "text": "\"Das ist eine heikle Angelegenheit – da halte ich mich besser raus!\"  2. Ein brandheißes Thema - da fass ich lieber nicht rein, sonst verbrenn ich mir die Finger!  3. Das ist eine heikle Sache – ich bleibe lieber außen vor!"}]'::jsonb, 'A haass Eisn!'),
  ('de-eisn-aufschdoeoen', 'de Eisn aufschdöön', '', '', '', 'Tod und Sterben auf Wienerisch', 'die Eisen aufstellen', '[{"kategorie": "wörtlich", "text": "\"die Schuheisen aufstellen\""}, {"kategorie": "", "text": "das Zeitliche segnen"}, {"kategorie": "", "text": "[[de]] Bock aufschdöön"}, {"kategorie": "", "text": "[[die]] Patschen strecken"}, {"kategorie": "", "text": "[[ein]] Bankerl reißen"}, {"kategorie": "", "text": "[[ins]] Gras beißen"}, {"kategorie": "", "text": "[[sich]] die Erdäpfel von unten anschauen"}]'::jsonb, ''),
  ('dea-hod-ane-noch-da-aundan-grauchd-bisa-de-eisn-aufgschdoeoed-hod', 'Dea hod ane noch da aundan grauchd, bisa de Eisn aufgschdööd hod!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der hat eine nach der anderen geraucht, bis er die Schuheisen aufgestellt hat!', '[{"kategorie": "wörtlich", "text": "\"Der hat geraucht wie ein Schlot, bis er das Zeitliche gesegnet hat!\"  2. Der hat sein Leben lang geraucht wie ein Kaminkehrer, bis er ein [[Bankerl]] g''riss''n hat!  3. Er war sein ganzes Leben lang Kettenraucher, bis er die [[Patschen]] gestreckt hat!"}]'::jsonb, 'de Eisn aufschdöön'),
  ('do-foad-de-eisnbauhn-driiwa', 'Do foad de Eisnbauhn driiwa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da fährt die Eisenbahn drüber!', '[{"kategorie": "fig.", "text": "\"Das ist so sicher wie das Amen im Gebet!\"  2. \"Komme, was wolle – das steht!\"  3. Dabei bleibt es - was auch immer geschieht!"}]'::jsonb, ''),
  ('von-foabige-eislutschka-traaman', 'von foabige Eislutschka traaman', '', '', '', '', 'von farbigen Eislutschern träumen', '[{"kategorie": "wörtlich", "text": "\"von bunten Eislutschern träumen\""}, {"kategorie": "fig.", "text": "\"von einer bunten, heilen Welt träumen\""}, {"kategorie": "", "text": "\"bunte Luftschlösser bauen\""}, {"kategorie": "", "text": "\"von bunten Zuckerwattewolken träumen\""}]'::jsonb, ''),
