  ('in-volla-montua', 'in volla Montua', '', '', '', '', 'in voller Montur', '[{"kategorie": "wörtlich", "text": "\"in voller Ausrüstung\" (vom französischen \"monture\"=\"Ausrüstung\")"}, {"kategorie": "", "text": "in voller Uniform, in voller Dienstkleidung, in vollem Arbeitsgewand"}, {"kategorie": "scherzhaft für", "text": "in voller Festtagskleidung, [[in]] vollem Wichs"}]'::jsonb, ''),
