  ('an-faadn-moong-haum', 'an faadn Moong haum', '', '', '', '', 'einen faden Magen haben', '[{"kategorie": "wörtlich", "text": "\"einen trägen Magen haben\""}, {"kategorie": "", "text": "Sodbrennen haben"}, {"kategorie": "", "text": "ein Brennen im Magen verspüren"}]'::jsonb, ''),
  ('an-brennadn-moong-haum', 'an brennadn Moong haum', '', '', '', '', 'einen brennden Magen haben', '[{"kategorie": "wörtlich", "text": "\"ein Brennen im Magen verspüren\""}, {"kategorie": "", "text": "Sodbrennen haben"}, {"kategorie": "", "text": "[[einen]] faden Magen haben"}]'::jsonb, ''),
  ('do-hods-an-foodn', 'Do hods an Foodn!', '', '', '', '', 'Da hat''s einen Faden', '[{"kategorie": "wörtlich, ursprünglich ein von Seidenspinnern geprägter Ausdruck, die jeden überzähligen Faden mühsam mit der Pinzette zu entfernen hatten", "text": "(fig.) Da stimmt etwas nicht!  Da gibt es ein Problem!  Da hakt es irgendwo!  2. (Bedeutungserweiterung zu \"Hindernis, das jede Outdoor-Aktivität verhindert):  Da hat''s eine Kälte!  Da friert einem die Nase ab! Da herrscht sibirische Kälte! Da ist es so kalt, dass die Eiszapfen wachsen!"}]'::jsonb, ''),
  ('do-hods-an-zopfn', 'Do hods an Zopfn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da hat''s einen Zapfen!', '[{"kategorie": "wörtlich, \"Zapfen\"=\"Kurzform für \"Eiszapfen\"", "text": "Da hat''s eine Eiseskälte!  2. Da friert einem die Nase ab!  3. Da ist es so kalt, dass die Eiszapfen wachsen!"}]'::jsonb, ''),
  ('de-wiisn-hintan-haus-bringt-drei-fadl-hei', 'De Wiisn hintan haus bringt drei Fadl Hei!', '', '', '', '', 'Die Wiese hinter dem Haus bringt drei Fadl Heu!', '[{"kategorie": "", "text": "Die Wiese hinter dem Haus liefert genug Heu für drei Wagenladungen!  2. Von der Wiese hinter dem Haus kann man drei Wagenladungen Heu machen!"}]'::jsonb, ''),
  ('a-faandal-haumn', 'a Faandal haumn', '', '', '', '', 'ein Fahnderl haben', '[{"kategorie": "", "text": "eine Fahne haben"}, {"kategorie": "", "text": "intensiv nach Alkohol riechen"}]'::jsonb, ''),
  ('reib-ma-de-faun', 'Reib ma de Faun!', '', '', '', '', 'Reibe mir die Fahne!', '[{"kategorie": "", "text": "Gib mir die Hand!  2. Hand drauf!  3. Schlag ein!"}]'::jsonb, ''),
  ('de-faun-pockn', 'de Faun pockn', '', '', '', '', 'die Fahne packen', '[{"kategorie": "", "text": "für etwas geradestehen"}, {"kategorie": "", "text": "die alleinige Verantwortung für etwas übernehmen"}]'::jsonb, ''),
  ('an-foara-mochn', 'an Foara mochn', '', '', '', '', 'einen Fahrer machen', '[{"kategorie": "", "text": "eine Nummer schieben"}, {"kategorie": "", "text": "einen [[Rutscher]] machen,  4. an [[Schdessa]] mochn"}]'::jsonb, ''),
  ('kaan-foara-mochn', 'kaan Foara mochn', '', '', '', '', 'keinen Fahrer machen', '[{"kategorie": "wörtlich", "text": "\"keinen Treffer landen\""}, {"kategorie": "", "text": "keinen Erfolg haben, kläglich scheitern, leer ausgehen"}, {"kategorie": "sexuell, scherzhaft für", "text": "\"keinen Stich machen\", \"nicht zum Einlochen kommen\", ohne [[Bumserl]] schlafen gehen, [[kaan]] Pecka mochn"}]'::jsonb, ''),
  ('foar-ums-eck', 'Foar-ums-Eck', '', '', '', '', 'Fahr-ums-Eck', '[{"kategorie": "wörtlich", "text": "1. \"um die Ecke fahrendes Ding\" (Determinativkompositum aus \"fahren\"=\"gleiten\" und \"ums Eck\"=\"um die Ecke\")"}, {"kategorie": "scherzhaft für", "text": "\"Besen, der um die Ecke kehrt\", Kehrwisch, Wischmopp"}]'::jsonb, ''),
  ('des-follate-haum', 'des Follate haum', '', '', '', '', 'das Fallerte haben', '[{"kategorie": "wörtlich", "text": "\"die Fallkrankheit haben\" (in Anspielung darauf, dass Epilepsiekranke oft unkontrolliert zu Boden fallen)"}, {"kategorie": "med.", "text": "an Epilepsie leiden, unter epileptischen Anfällen leiden, an Fallsucht leiden"}, {"kategorie": "allg.", "text": "\"sturzanfällig sein\";  auf wackeligen Beinen stehen, stolperanfällig sein, \"leicht zu Sturz kommen\""}]'::jsonb, ''),
  ('s-follate', 's Follate', '', '', '', '', 'das Fallerte', '[{"kategorie": "wörtlich", "text": "\"Fallkrankheit\" (vom mittelhochdeutschen \"vallen\"=\"stürzen\")"}, {"kategorie": "med.", "text": "Epilepsie, Fallsucht, epileptische Erkrankung"}, {"kategorie": "allg.", "text": "Sturzanfälligkeit, Trittunsicherheit, Stolperanfälligkeit"}]'::jsonb, ''),
  ('du-foischa-fuffzga', 'Du foischa Fuffzga!', '', '', '', '', 'Du falscher Fünfziger!', '[{"kategorie": "", "text": "Du hinterhältiger Schuft!  2. Du gemeiner Verräter!  3. Du hinterlistiger Hund!  4. Du falsche Schlange! (Insbesondere in der ersten Hälfte des 20. Jahrhunderts wurden häufig gefälschte Fünzigpfennigmünzen in Umlauf gebracht. Ein \"falscher Fünfziger\" war somit ein Synonym für eine Fälschung, und die Redewendung wurde übertragen auf Menschen, die als unehrlich, betrügerisch oder heuchlerisch gelten)"}]'::jsonb, ''),
  ('du-foischa-siibzeena', 'Du foischa Siibzeena!', '', '', '', '', 'Du falscher Siebzehner!', '[{"kategorie": "", "text": "Du hinterhältiger Schuft!  2. Du gemeiner Betrüger!  3. Du hinterlistiger Hund!  4. Du falsche Schlange!  (Insbesondere im 18. Jahrhundert wurden häufig gefälschte 17-Kreuzer-Münzen in Umlauf gebracht. Ein \"falscher Siebzehner\" war somit ein Synonym für eine Fälschung, und die Redewendung wurde übertragen auf Menschen, die als unehrlich, betrügerisch oder heuchlerisch gelten)"}]'::jsonb, ''),
  ('foischa-hund', 'foischa Hund', '', '', '', '', 'falscher Hund', '[{"kategorie": "wörtlich", "text": "\"unehrlicher Schuft\""}, {"kategorie": "", "text": "Intrigant, Lügner, Betrüger, [[Grfraßtsackl]], [[Haut]], [[Hackelschmeißer]], [[Arschkletzen]]"}]'::jsonb, ''),
  ('foischa-saumstog', 'foischa Saumstog', '', '', '', '', 'falscher Samstag', '[{"kategorie": "wörtlich", "text": "\"unechter Samstag\""}, {"kategorie": "scherzhaft für", "text": "Werktag vor einem gesetzlichen Feiertag"}, {"kategorie": "Deutschland", "text": "\"falscher Sonnabend\""}]'::jsonb, ''),
  ('foischa-hoos', 'foischa Hoos', '', '', '', '', 'falscher Hase', '[{"kategorie": "scherzhaft für", "text": "[[faschierter Braten]] (vom althochdeutschen \"falsc\"=\"unecht\" und \"has\"=\"Hase\")"}, {"kategorie": "Deutschland", "text": "\"Hackbraten\" (Zur Erklärung: Der Hasenbraten war einst ein beliebtes Sonntagsessen. Nach dem Zweiten Weltkrieg nahm die Hasenpopulation aber derart dramatisch ab, dass sich die Leute eine Alternative suchen mussten. So wurde stattdessen [[Faschiertes]] [Hackfleisch] zu einem Braten geformt und in einer Auflaufform in den Ofen gegeben)"}]'::jsonb, ''),
  ('da-faam-aufn-bia-is-scho-zsaummgfoin', 'Da Faam aufn Bia is scho zsaummgfoin!', '', '', '', '', 'Der Fam auf dem Bier ist zusammengefallen!', '[{"kategorie": "wörtlich", "text": "\"Der Schaum auf dem Bier ist in sich zusammengefallen!\"  2. Die Schaumkrone auf dem Bier ist eingestürzt!"}]'::jsonb, ''),
  ('in-familiinschdrumpf-auswinden', 'in Familiinschdrumpf auswinden', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'den Familienstrumpf auswinden', '[{"kategorie": "wörtlich", "text": "\"den Penis auswinden\""}, {"kategorie": "scherzhaft für", "text": "Wasser lassen, urinieren, [[seichen]],  pinkeln, [[brunzen]], [[schiffen]], [[den]] Kasperl schnäuzen"}]'::jsonb, ''),
  ('woat-auf-mi-i-gee-nua-schnoeoe-in-familiinschdrumpf-auswindn', 'Woat auf mi, I gee nua schnöö in Familiinschdrumpf auswindn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Warte auf mich - ich gehe nur schnell meinen Familienstrumpf auswinden!', '[{"kategorie": "wörtlich", "text": "\"Warte auf mich - ich geh'' nur schnell meine Familiengießkanne leeren!\"  2. Bin gleich wieder da - muss nur kurz den Stammhalter entleeren!  3. Warte kurz - ich muss meinen Familienschlauch entknoten und kurz mal Wasser lassen!"}]'::jsonb, ''),
  ('friara-woara-a-freia-mau-jetza-troogda-a-faungeisn-mit-gravua', 'Friara woara a freia Mau - jetza troogda a Faungeisn mit Gravua!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Früher war er ein freier Mann – heute trägt er ein Fangeisen mit Gravur!', '[{"kategorie": "wörtlich", "text": "\"Früher war er ein freier Mann – heute trägt er einen Ehering mit Gravur!\"  2. Vor der Hochzeit war er ein freier Mann – doch jetzt hängt das goldene Fangeisen an seinem Finger!\"  3. Früher war er noch ein freier Vogel - heute trägt er ein goldenes Fangeisen um den Finger und hat s''Fliegen verlernt!"}]'::jsonb, ''),
  ('iwaroi-im-woid-liing-no-de-rostign-faungeisn-owa-wehe-du-brunzd-auf-an-baam-des-is-daunn-umwoedvaschmutzung', 'Iwaroi im Woid liing no de rostign Faungeisn - owa wehe, du brunzd auf an Baam, des is daunn Umwödvaschmutzung!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Überall im Wald liegen noch die rostigen Fangeisen - aber wehe, du brunzt auf einen Baum, das ist dann Umweltverschmutzung!', '[{"kategorie": "wörtlich", "text": "\"Überall im Wald liegen noch die rostigen Fangeisen - aber wehe, du pisst gegen ''nen Baum – das ist dann ‚Umweltverschmutzung‘!\"  2. Im ganzen Wald liegen noch die verrosteten Tierfallen herum – aber wehe, du machst an einen Baum, dann bist du gleich ein Umweltverbrecher!  3. Die alten Eisenfallen rosten still vor sich hin – doch wer am Baum Wasser lässt, begeht ein Umweltverbrechen!"}]'::jsonb, ''),
  ('si-ane-eifaungan', 'si ane eifaungan', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich eine einfangen', '[{"kategorie": "wörtlich", "text": "\"sich eine Ohrfeige einfangen\" (vom mittelhochdeutschen \"vangen\"=\"fangen\")"}, {"kategorie": "allg.", "text": "eine Ohrfeige verpasst bekommen"}, {"kategorie": "", "text": "eine Ohrfeige kassieren, einstecken"}]'::jsonb, 'Waunnst de Goschn no weida aufreissd, faungst da ane ei!'),
  ('waunnst-de-goschn-no-weida-aufreissd-faungst-da-ane-ei', 'Waunnst de Goschn no weida aufreissd, faungst da ane ei!', '', '', '', 'Wiener Gaunersprache', 'Wenn du die Goschen noch weiter aufreißt, fängst du dir eine ein!', '[{"kategorie": "wörtlich", "text": "\"Wenn du die Klappe noch weiter aufreißt, fängst du dir eine ein!\"  2. Noch ein Ton – und du fängst dir eine Faust ein!  3. Wenn du die Fresse weiter so aufreißt, fängst du dir eine Watschen ein!"}]'::jsonb, 'si ane eifaungan'),
  ('faung-mi-do', 'Faung mi do!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fang mich doch!', '[{"kategorie": "wörtlich", "text": "\"Fang mich, wenn du kannst!\"  2. Krieg mich doch!  3. Los, versuch mich zu schnappen!"}]'::jsonb, ''),
  ('ane-faungan', 'ane faungan', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine fangen', '[{"kategorie": "wörtlich", "text": "\"sich eine Ohrfeige einfangen\" (vom mittelhochdeutschen \"vangen\"=\"fangen\")"}, {"kategorie": "", "text": "eine Ohrfeige verpasst bekommen"}, {"kategorie": "", "text": "eine Ohrfeige kassieren, einstecken"}]'::jsonb, 'Glei ramsd a Fazku oo!'),
  ('da-gooli-schiid-si-au-und-faungd-kan-anzign-boin', 'Da Gooli schiid si au und faungd kan anzign Boin!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Goalie schüttet sich an und fängt keinen einzigen Ball!', '[{"kategorie": "wörtlich", "text": "\"Der Tormann macht sich nass und fängt keinen einzigen Ball!\"  2. Der Tormann stellt sich stümperhaft an und fängt keinen einzigen Ball!  3. Der Torhüter hat zwei linke Hände und fängt keinen einzigen Ball!"}]'::jsonb, ''),
  ('schau-ma-wos-ma-faungan-kenna', 'Schau ma, wos ma faungan kenna!', '', '', '', 'Wiener Gaunersprache', 'Schauen wir mal, was wir fangen können!', '[{"kategorie": "wörtlich", "text": "\"Schauen wir mal, was wir mitgehen lassen können!\"  2. Schauen wir mal, was wir unauffällig einsacken können!  3. Mal sehen, was hier so lose rumliegt!"}]'::jsonb, ''),
  ('faungal-spueuen', 'Faungal spüün', '', '', '', '', 'Fangerl spielen', '[{"kategorie": "wörtlich", "text": "\"Fangen spielen\" (Laufspiel, bei dem der Fänger seine Mitspieler mittels Handberührung fassen muss)"}, {"kategorie": "allg., Kindersprache", "text": "\"Verfolgungsjagd spielen\", \"Katz und Maus spielen\", \"Räuber und Gendarm spielen\", \"Häschen spielen\", [[Fotschi]] schbüün"}]'::jsonb, ''),
  ('des-woa-fia-d-fanni-tant', 'Des woa fia d''Fanni-Tant', '', '', '', '', 'Das war für die Tante Fanni', '[{"kategorie": "", "text": "Das war [[für]] die Katz!  2. Das war total umsonst!  3. Das war komplett vergebens!  4. Das war für''n [[Hugo]]!  5. Das waren nur [[leere]] Kilometer!"}]'::jsonb, ''),
  ('a-guade-foab-haum', 'a guade Foab haum', '', '', '', '', 'eine gute Farbe haben', '[{"kategorie": "", "text": "eine gesunde Gesichtsfarbe haben"}, {"kategorie": "", "text": "blühend und gesund aussehen"}, {"kategorie": "", "text": "ein sonnengebräuntes Gesicht haben"}]'::jsonb, ''),
  ('a-foab-aufreissn', 'a Foab aufreissn', '', '', '', '', 'eine Farbe aufreißen', '[{"kategorie": "wörtlich", "text": "eine sommerliche Bräune bekommen, ein sonnengebräuntes Gesicht bekommen"}, {"kategorie": "fig.", "text": "rot werden, schamhaft erröten"}]'::jsonb, ''),
  ('foab-schindn', 'Foab schindn', '', '', '', '', 'Farbe schinden', '[{"kategorie": "wörtlich", "text": "\"mit aller Gewalt sommerlich gebräunt aussehen wollen\""}, {"kategorie": "", "text": "unaufhörlich auf der Sonnenbank liegen, regelmäßig ins Solarium gehen"}]'::jsonb, ''),
  ('si-is-a-rechds-foafal', 'Si is a rechds Foafal!', '', '', '', '', 'Sie ist ein rechtes Farferl!', '[{"kategorie": "", "text": "Sie ist wahrhaft ein schüchternes Reh!  2. Sie ist ein echtes Mauerblümchen!  3. (Deutschland): Sie ist eine echte Zimperliese!"}]'::jsonb, ''),
  ('wem-duachd-faschiamaschin-draan', 'wem duachd Faschiamaschin draan', '', '', '', '', 'jemanden durch die Faschiermaschine drehen', '[{"kategorie": "wörtlich", "text": "\"jemanden durch den Fleischwolf drehen\""}, {"kategorie": "", "text": "jemanden durch die Mangel drehen"}, {"kategorie": "", "text": "jemandem ans Leder gehen"}, {"kategorie": "", "text": "[[wem duachs Kanäugitta passian]]"}, {"kategorie": "", "text": "[[wem katolisch mochn]]"}]'::jsonb, ''),
  ('wem-duachd-fleischmaschin-draan', 'wem duachd Fleischmaschin draan', '', '', '', '', 'jemanden durch die Fleischmaschine drehen', '[{"kategorie": "wörtlich", "text": "\"jemanden durch den Fleischwolf drehen\""}, {"kategorie": "", "text": "jemanden durch die Mangel drehen"}, {"kategorie": "", "text": "jemandem ans Leder gehen"}, {"kategorie": "", "text": "[[wem duachs Kanäugitta passian]]"}, {"kategorie": "", "text": "[[wem katolisch mochn]]"}]'::jsonb, ''),
  ('wem-duachd-wuaschdmaschin-draan', 'wem duachd Wuaschdmaschin draan', '', '', '', '', 'jemanden durch die Wurstmaschine drehen', '[{"kategorie": "wörtlich", "text": "\"jemanden durch den Fleischwolf drehen\""}, {"kategorie": "", "text": "jemanden durch die Mangel drehen"}, {"kategorie": "", "text": "jemandem ans Leder gehen"}, {"kategorie": "", "text": "[[wem duachs Kanäugitta passian]]"}, {"kategorie": "", "text": "[[wem katolisch mochn]]"}]'::jsonb, ''),
  ('do-faeuds', 'Do fäuds!', '', '', '', '', 'Da fäult es!', '[{"kategorie": "", "text": "Hier stinkt''s!  2. Hier riecht''s faulig!  3. [[Do]] niachdlts!"}]'::jsonb, ''),
  ('do-niachdlts', 'Do niachdlts!', '', '', '', '', 'Da nüachtelt es!', '[{"kategorie": "", "text": "Hier stinkt''s!  2. Hier riecht''s faulig!  3. [[Do]] fäuds!"}]'::jsonb, ''),
  ('waunnsd-di-no-laung-schbueuesd-kassiasd-a-faustwaatschn', 'Waunnsd di no laung schbüüsd, kassiasd a Faustwaatschn!', '', '', '', 'Wiener Gaunersprache', 'Wenn du dich noch lange spielst, kassierst du eine Faustwatsche!', '[{"kategorie": "wörtlich", "text": "\"Wenn du so weiter machst, setzt’s gleich eine Faust in die Fresse!\"  2. Wenn du weiter so provozierst, pfeift gleich meine Faust in dein Gesicht!  3. Wenn du’s drauf anlegst, landest du mit dem Gesicht in meiner Faust!"}]'::jsonb, ''),
  ('im-19-joahundad-woas-gaung-und-gaebe-dass-schdudentn-mensuan-ausgfochtn-haum', 'Im 19. Joahundad woas gaung und gäbe, dass Schdudentn Mensuan ausgfochtn haum!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Im 19. Jahrhundert war es gang und gäbe, dass Studenten Mensuren ausgefochten haben!', '[{"kategorie": "wörtlich", "text": "\"Im 19. Jahrhundert war es unter Studenten üblich, Mensuren zu fechten!\"  2. Im 19. Jahrhundert war das Fechten akademischer Mensuren fester Bestandteil studentischer Kultur!  3. Akademische Fechtduelle waren unter Studenten des 19. Jahrhunderts gang und gäbe!"}]'::jsonb, ''),
  ('bei-da-koarlskiachn-san-de-fechtbriada-friara-gsessn-und-haum-beedld-wia-kraunke-hund', 'Bei da Koarlskiachn san de Fechtbriada friara gsessn und haum beedld wia kraunke Hund!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Bei der Karlskirche sind die Fechtbrüder früher gesessen und haben gebettelt wie kranke Hunde!', '[{"kategorie": "wörtlich", "text": "\"Bei der Karlskirche sind die Bettelbrüder früher gesessen und haben um Almosen gewinselt!\"  2. Vor der Karlskirche saßen einst die Bettelbrüder, demütig mit offenen Händen, und baten um milde Gaben!  3. Bettelbrüder suchten damals Schutz an der Karlskirche und hofften auf die Spenden der Gläubigen!"}]'::jsonb, ''),
  ('do-geeds-zua-wiarin-ana-fechtschui', 'Do geeds zua wiarin ana Fechtschui!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Da geht es zu wie in einer Fechtschule!', '[{"kategorie": "wörtlich", "text": "\"Da herrscht ein wildes, chaotisches Durcheinander wie in einer Fechtschule!\"  2. Da geht’s drunter und drüber wie in einer Fechtschule!  3. Da herrscht ein derart wildes Chaos, dass man glaubt, man wär in einer Fechtschule! (\"Fechtschule\" = historische Bezeichnung für organisierte öffentliche Fechtübungen, die im deutschsprachigen Raum vom 14. bis zum 17. Jahrhundert verbreitet waren. Geleitet von sogenannten Fechtmeistern, oft Mitgliedern von Bruderschaften wie der Marxbrüder oder Federfechter. Es handelte sich um öffentliche Kampfveranstaltungen, bei denen Schwert-, Degen- oder Stangenwaffentechniken präsentiert und geübt wurden – sowohl zum Training als auch zur Unterhaltung. Häufig in Gasthäusern, Tanzsälen oder Freiflächen abgehalten)"}]'::jsonb, ''),
  ('do-schdaubts-in-da-fechtschui', 'Do schdaubts in da Fechtschui!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Da staubt es in der Fechtschule!', '[{"kategorie": "wörtlich", "text": "\"Da staubt es am Fechtplatz!\"  2. (fig.) Da stimmt etwas nicht!  3. Da ist etwas faul!  4. Da geht''s nicht mit rechten Dingen zu! (\"Fechtschule\" = historische Bezeichnung für organisierte öffentliche Fechtübungen, die im deutschsprachigen Raum vom 14. bis zum 17. Jahrhundert verbreitet waren. Geleitet von sogenannten Fechtmeistern, oft Mitgliedern von Bruderschaften wie der Marxbrüder oder Federfechter. Es handelte sich um öffentliche Kampfveranstaltungen, bei denen Schwert-, Degen- oder Stangenwaffentechniken präsentiert und geübt wurden – sowohl zum Training als auch zur Unterhaltung. Häufig in Gasthäusern, Tanzsälen oder Freiflächen abgehalten)"}]'::jsonb, ''),
  ('do-schdinkts-in-da-fechtschui', 'Do schdinkts in da Fechtschui!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Da stinkt es in der Fechtschule!', '[{"kategorie": "wörtlich", "text": "\"Da stinkt es am Fechtplatz!\"  2. (fig.) Da stimmt etwas nicht!  3. Da ist etwas faul!  4. Da geht''s nicht mit rechten Dingen zu! (\"Fechtschule\" = historische Bezeichnung für organisierte öffentliche Fechtübungen, die im deutschsprachigen Raum vom 14. bis zum 17. Jahrhundert verbreitet waren. Geleitet von sogenannten Fechtmeistern, oft Mitgliedern von Bruderschaften wie der Marxbrüder oder Federfechter. Es handelte sich um öffentliche Kampfveranstaltungen, bei denen Schwert-, Degen- oder Stangenwaffentechniken präsentiert und geübt wurden – sowohl zum Training als auch zur Unterhaltung. Häufig in Gasthäusern, Tanzsälen oder Freiflächen abgehalten)"}]'::jsonb, ''),
  ('si-a-feedal-aum-huat-schdeckn', 'si a Feedal aum Huat schdeckn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich ein Federl an den Hut stecken', '[{"kategorie": "wörtlich", "text": "\"sich ein Federchen an den Hut stecken\""}, {"kategorie": "fig.", "text": "sich etwas auf die Fahne schreiben"}, {"kategorie": "", "text": "sich einen Orden anstecken"}, {"kategorie": "", "text": "einen Pluspunkt auf dem eigenen Erfolgskonsto verbuchen"}]'::jsonb, ''),
  ('noch-da-gaunz-hockn-deaf-i-ma-jetzt-ruhig-a-feedal-aum-huat-schdeckn', 'Noch da gaunz Hockn deaf I ma jetzt ruhig a Feedal aum Huat schdeckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach der ganzen Hacken darf ich mir jetzt ruhig ein Federl an den Hut stecken!', '[{"kategorie": "wörtlich", "text": "\"Nach all der Arbeit darf ich mir jetzt ruhig ein kleines Federchen an den Hut stecken!\"  2. Nach all der Mühe darf ich mir den Erfolg jetzt guten Gewissens auf die Fahne schreiben!  3. Nach all der Anstrengung darf ich mir jetzt ein stilles Federchen des Stolzes an meinem Hut heften!"}]'::jsonb, 'si a Feedal aum Huat schdeckn'),
  ('da-rudi-dea-hund-des-is-a-deppada-fedarant-dea-wueue-ned-mitgee-eidiiwaen', 'Da Rudi, dea Hund, des is a deppada Fedarant - dea wüü ned mitgee eidiiwän!', '', '', '', 'Wiener Gaunersprache', 'Der Rudi, der Hund, das ist ein depperter Fedarant - der will zum Eindübeln nicht mitgehen!', '[{"kategorie": "wörtlich", "text": "\"Der Rudi, der Hund, das ist ein depperter Schisser - der will nicht mitkommen zum Einbrechen!\"  2. Der Rudi, dieser depperte Hund, ist einfach ein Feigling – der hat zu viel Schiss, um mit uns einbrechen zu gehen!  3. Rudi, der feige Sack – drückt sich natürlich wieder, wenn’s ernst wird - der kriegt schon Schweißausbrüche, wenn er nur an einen Dietrich denkt!"}]'::jsonb, ''),
  ('mit-dea-schisshittn-brauchsd-an-bruch-ned-planan-dea-ziddad-jo-schoo-beim-tiarlaufschbean', 'Mit dea Schisshittn brauchsd an Bruch ned planan – dea ziddad jo schoo beim Tiarlaufschbean!', '', '', '', 'Wiener Gaunersprache', 'Mit dieser Schisshütten brauchst du einen Einbruch nicht zu planen - der zittert ja schon beim Türaufsperren!', '[{"kategorie": "wörtlich", "text": "Mit so einem Schisser brauchst du keinen Einbruch zu planen – der zittert ja schon beim Türaufsperren!“  2. Mit so einem feigen Sack brauchst du keinen Einbruch starten – der zittert ja schon, wenn die Türe aufschnappt!  3. Der Hosenscheißer braucht beim Bruch mehr Windel als Werkzeug!"}]'::jsonb, ''),
  ('a-kniawoogla-bei-an-bruch-is-wiara-saandla-in-da-oopa-komplett-foeoe-aum-plotz', 'A Kniawoogla bei an Bruch is wiara Saandla in da Oopa – komplett föö aum Plotz!', '', '', '', 'Wiener Gaunersprache', 'Ein Kniewackler bei einem Bruch ist wie ein Sandler in der Oper – komplett fehl am Platz!', '[{"kategorie": "wörtlich", "text": "\"Ein Schisser bei einem Einbruch ist wie ein Sandler in der Oper – komplett fehl am Platz!\"  2. Ein Schisser beim Einbruch ist wie ein Obdachloser in der Oper - peinlich und verhaut alles!  3. Ein Angsthase auf Einbruchstour  ist wie ein Veganer auf der Grillparty – eher hinderlich!"}]'::jsonb, ''),
  ('de-feedan-haum', 'de Feedan haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Federn haben', '[{"kategorie": "wörtlich", "text": "\"Federn lassen\" (aus der Jägersprache: ein Tier \"lässt Federn\", wenn es sich vor einem Angriff oder einer Gefahr in Sicherheit bringt, zumeist durch Flucht, wobei die \"Federn\" hierbei sinnbildlich für ein sichtbares Zeichen von Panik oder Angst stehen)"}, {"kategorie": "", "text": "Schiss haben"}, {"kategorie": "", "text": "Angst haben"}, {"kategorie": "", "text": "Muffensausen haben"}]'::jsonb, ''),
  ('feedan-lossn', 'Feedan lossn', '', '', '', 'Wiener Sprüche, die sitzen!', 'Federn lassen', '[{"kategorie": "wörtlich", "text": "\"Federn lassen\" (aus der Jägersprache: ein Tier \"lässt Federn\", wenn es sich vor einem Angriff oder einer Gefahr in Sicherheit bringt, zumeist durch Flucht, wobei die \"Federn\" hierbei sinnbildlich für ein sichtbares Zeichen von Panik oder Angst stehen)"}, {"kategorie": "fig.", "text": "nicht ungeschoren davonkommen, den Kürzeren ziehen, \"bluten müssen\""}, {"kategorie": "scherzhaft für", "text": "\"Haare lassen\", sich die Haare scheren lassen, sich die langen Zotten trimmen lassen"}]'::jsonb, 'Ea hod si min Foischn augleegd und uandlich Feedan lossn miassn!'),
  ('ea-hod-si-min-foischn-augleegd-und-uandlich-feedan-lossn-miassn', 'Ea hod si min Foischn augleegd und uandlich Feedan lossn miassn!', '', '', '', 'Wiener Gaunersprache', 'Er hat sich mit dem Falschen angelegt und ordentlich Federn lassen müssen!', '[{"kategorie": "wörtlich", "text": "\" Er hat den Falschen herausgefordert – und teuer dafür bezahlt!\"  2. Er ist an den Falschen geraten und musste dafür ordentlich bluten!  3. Der hat sich mit dem falschen Typen angelegt und ist dabei nicht ungeschoren davongekommen!"}]'::jsonb, 'Feedan lossn'),
  ('zua-schdroof-haums-eam-gfeedad-und-aum-schaundkoan-zua-schau-gschdoeoed', 'Zua Schdroof haums eam gfeedad und aum Schaundkoan zua Schau gschdööd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Zur Strafe haben sie ihn gefedert und auf dem Schandkarren zur Schau gstellt!', '[{"kategorie": "wörtlich", "text": "\"Zur Strafe hat man ihn mit Teer eingestrichen, dann mit Vogelfedern beworfen und schließlich auf dem Schandkarren zur Schau gestellt!\"  2. Die Strafe bestand darin, den Delinquenten zu teeren, dann zu federn und schließlich auf dem Schandkarren zur Schau zu stellen!  3. Gefedert und gebrandmarkt, saß er auf dem Schandkarren und trug das Symbol der Verachtung auf nackter Haut!"}]'::jsonb, ''),
  ('si-haum-eam-ned-kritisiad-si-haum-eam-auf-offana-bueuene-gfeedad', 'Si haum eam ned kritisiad, si haum eam auf offana Büüne gfeedad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie haben ihn nicht kritisiert – sie haben ihn auf offener Bühne gefedert!', '[{"kategorie": "wörtlich", "text": "\"Sie haben ihn nicht kritisiert – sie haben ihn auf offener Bühne bloßgestellt!\"  2. Das war keine Kritik – das war eine öffentliche Hinrichtung!  3. Die haben ihn nicht kritisiert – die haben ihn vor versammelter Mannschaft auseinandergenommen!"}]'::jsonb, ''),
  ('ea-hod-si-beim-pookan-mit-de-foischn-freind-eilossn-aum-schluss-haums-eam-olle-gfeedad', 'Ea hod si beim Pookan mit de foischn Freind eilossn - aum Schluss haums eam olle gfeedad!', '', '', '', 'Wiener Gaunersprache', 'Er hat sich beim Pokern mit den falschen Freunden eingelassen – am Schluss haben sie ihn alle gefedert!', '[{"kategorie": "wörtlich", "text": "\"Er hat sich beim Pokern mit den falschen Freunden eingelassen – am Ende haben sie ihn alle gerupft!\"  2. Er hat sich beim Pokern mit den falschen Freunden eingelassen –am Ende haben sie ihn bis auf die Unterhose ausgenommen!  3. Er hat sich auf ein Pokerspiel mit den falschen Leuten eingelassen – und die haben ihn zum Schluss bis aufs Hemd blank gemacht!"}]'::jsonb, ''),
  ('dea-lochd-wiara-engl-owa-frissd-di-wia-da-deifae', 'Dea lochd wiara Engl - owa frissd di wia da Deifä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der lacht wie ein Engel - aber frisst dich wie der Teufel!', '[{"kategorie": "wörtlich", "text": "\"Der sieht aus wie ein Heiland – aber frisst dich wie ein seelenhungriger Teufel !\"  2. Du denkst, du datest einen Engel – und wachst mit einem Teufel im Herzen auf!  3. Der lächelt wie dein bester Freund – und frisst dir die Seele auf wie ein böser Teufel!"}]'::jsonb, ''),
  ('da-joschi-is-a-echta-deifae-dea-traud-si-ollas', 'Da Joschi is a echta Deifä - dea traud si ollas!', '', '', '', 'Wiener Gaunersprache', 'Der Joschi ist ein echter Teufel - der traut sich alles!', '[{"kategorie": "wörtlich", "text": "\"Der Joschi ist ein echter Draufgänger -  der schreckt vor nichts zurück!\"  2. Der Joschi ist ein Teufelskerl – ihm ist kein Risiko zu groß!  3. Joschi ist ein echter Haudegen – der zieht alles durch, egal was kommt!"}]'::jsonb, ''),
  ('wea-min-deifae-taunzd-deaf-si-ned-wundan-waunns-noch-schweefae-faeud', 'Wea min Deifä taunzd, deaf si ned wundan, waunns noch Schweefä fäud!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wer mit dem Teufel tanzt, darf sich nicht wundern, wenn''s nach Schwefel fäult!', '[{"kategorie": "wörtlich", "text": "\"Wer mit dem Teufel tanzt, darf sich nicht wundern, wenn''s nach Schwefel stinkt!\"  2. Wer mit dem Feuer spielt, darf den Rauch nicht scheuen!  3. Wer dem Teufel die Hand gibt, braucht sich nicht zu wundern, wenn sie nachher nach Schwefel stinkt und brennt!"}]'::jsonb, ''),
  ('de-feedan-orasian', 'de Feedan orasian', '', '', '', 'Wiener Sprüche, die sitzen!', 'die Federn abrasieren', '[{"kategorie": "wörtlich, scherzhaft für", "text": "\"die Haare abrasieren\""}, {"kategorie": "", "text": "\"die Zotten scheren\""}, {"kategorie": "", "text": "\"die Mähne abfräsen\""}]'::jsonb, ''),
  ('in-hoeoemal-haums-de-laungan-feedan-komplett-orasiad-jetzt-eakennd-eam-kaana-mea', 'In Höömal haums de laungan Feedan komplett orasiad - jetzt eakennd eam kaana mea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem Helmut haben sie die langen Federn komplett abrasiert - jetzt erkennt ihn keiner mehr!', '[{"kategorie": "wörtlich", "text": "\"Dem Helmut haben sie die langen Haare komplett geschoren - jetzt erkennt ihn keiner mehr!\"  2. Dem Helmut haben sie die langen Zotten komplett abrasiert - jetzt ist er nicht mehr wiederzuerkennen!  3. Dem Helmut haben sie die lange Mähne komplett runtergefräst - niemand hätte ihn auf den ersten Blick erkannt!"}]'::jsonb, 'de Feedan orasian'),
  ('von-d-feedan-aufs-schdroo-kumma', 'von d''Feedan aufs Schdroo kumma', '', '', '', 'Wiener Sprüche, die sitzen!', 'von den Federn aufs Stroh kommen', '[{"kategorie": "wörtlich", "text": "\"von den Bettfedern aufs Stroh kommen\""}, {"kategorie": "fig.", "text": "vom Wohlstand in die Not abrutschen"}, {"kategorie": "", "text": "vom Thron ins Elend stürzen"}, {"kategorie": "", "text": "einen sozialen Abstieg erleiden, verkommen, verarmen, verelenden"}]'::jsonb, 'Da Hoibseidane is von d''Feedan aufs Schdroo kumman - und jetzt sitzta im Bau!'),
  ('da-hoibseidane-is-von-d-feedan-aufs-schdroo-kumman-und-jetzt-sitzta-im-bau', 'Da Hoibseidane is von d''Feedan aufs Schdroo kumman - und jetzt sitzta im Bau!', '', '', '', 'Wiener Gaunersprache', 'Der Halbseidene ist von den Federn aufs Stroh gekommen - und jetzt sitzt er im Bau!', '[{"kategorie": "wörtlich", "text": "\"Der Zuhälter ist vom Thron ins Elend gestürzt - und jetzt sitzt er im Gefängnis!\"  2. Der Oberstrizzi is weg vom Fenster – vom Ledersessel direkt in die Zelle!  3. Der [[Peitscherlbub]] ist gefallen - vom Wasserbett ins Gitterbett!"}]'::jsonb, 'von d''Feedan aufs Schdroo kumma'),
  ('wem-feedan', 'wem feedan', '', '', '', 'Wiener Gaunersprache', 'jemanden federn', '[{"kategorie": "wörtlich", "text": "\"jemandem die Federn rupfen\" (vom mittelhochdeutschen \"vedere\"=\"Feder\")"}, {"kategorie": "Gaunersprache", "text": "jemanden ums  Geld bringen, abzocken, ausnehmen, \"rupfen wie ein Huhn\""}]'::jsonb, 'I loss mi von dia sicha ned feedan - such da an Doodl mid an waachan Föö!'),
  ('i-loss-mi-von-dia-sicha-ned-feedan-such-da-an-doodl-mid-an-waachan-foeoe', 'I loss mi von dia sicha ned feedan - such da an Doodl mid an waachan Föö!', '', '', '', 'Wiener Gaunersprache', 'Ich lass mich von dir sicher nicht federn - such dir einen Dodel mit weicherem Fell!', '[{"kategorie": "wörtlich", "text": "\"Ich lass mich von dir sicher nicht rupfen wie ein Huhn - such dir einen Deppen mit weicherem Fell!\"  2. Ich lass mich von dir sicher nicht ausnehmen - such dir einen Trottel, der''s nicht merkt!  3. Ich lass mich von dir sicher nicht abzocken wie ein Idiot - da musst du früher aufstehen!"}]'::jsonb, ''),
  ('aum-feedanboi-gee', 'aum Feedanboi gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf den Federnball gehen', '[{"kategorie": "wörtlich", "text": "\"auf den Bettfedernball gehen\""}, {"kategorie": "scherzhaft für", "text": "zu Bett gehen, schlafen gehen, die Nachtuhe antreten"}]'::jsonb, ''),
  ('so-kinda-ob-in-de-puedschamas-es-wiad-zeit-aum-feedanboi-zgee', 'So, Kinda, ob in de Püdschamas - es wiad Zeit, aum Feedanboi zgee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So, Kinder – ab in die Pyjamas! Es wird Zeit, auf den Federnball zu gehen!', '[{"kategorie": "wörtlich", "text": "\"So, Kinder – ab in die Pyjamas! Es wird Zeit, den Bettfederntanz anzutreten!\"  2. Na los, meine Lieben – rein in die Schlafanzüge, es ist Zeit fürs Bett!  3. So, ihr Mäuse, Pyjamas anziehen - jetzt ist Schlafenszeit!"}]'::jsonb, ''),
  ('des-feigld-mi', 'Des feigld mi!', '', '', '', '', 'Das feigelt mich!', '[{"kategorie": "wörtlich", "text": "\"Das ärgert mich!\"  2. Das fuchst mich!  3. Das regt mich auf!"}]'::jsonb, ''),
  ('eam-hods-uandlich-higfeigld', 'Eam hods uandlich higfeigld!', '', '', '', '', 'Ihn hat es ordentlich hingefeigelt!', '[{"kategorie": "", "text": "Ihn hat es ordentlich hingeknallt!  2. Er ist mächtig hingeflogen!  3. Er hat einen wilden Abflug gemacht!"}]'::jsonb, ''),
  ('do-zuckt-ma-scho-da-feitl-in-da-toschn', 'Do zuckt ma scho da Feitl in da Toschn!', '', '', '', '', 'Da zuckt mir schon der Feitel in der Tasche!', '[{"kategorie": "", "text": "Da zuckt mir schon das Taschenmesser im Hosensack!  2. Da juckt mich schon das Klappmesser im Hosensack!"}]'::jsonb, ''),
  ('dea-is-a-festa-dillo', 'Dea is a festa Dillo!', '', '', '', '', 'Der ist ein fester Dillo!', '[{"kategorie": "wörtlich", "text": "Der ist ein ordentlicher Dussel!  2. Der ist ein Depp durch und durch!  3. Der ist ein gewaltiger Trottel!"}]'::jsonb, ''),
  ('fett-wia-de-russische-erdn', 'fett wia de russische Erdn', '', '', '', '', 'fett wie die russische Erde', '[{"kategorie": "", "text": "\"voll bis oben hin\""}, {"kategorie": "", "text": "besoffen bis unter die Haare"}, {"kategorie": "", "text": "blau wie ein Matrose"}, {"kategorie": "", "text": "[[fett]] wie eine Haubitzen"}, {"kategorie": "", "text": "[[fett]] wie ein Indianer (Zur Erklärung: Die Redewendung \"fett wie die russische Erde\" rührt daher, dass die Schwarzerdeböden Russlands einst als dier fruchtbarsten der Welt galten)"}]'::jsonb, ''),
  ('fett-wiara-hydrant', 'fett wiara Hydrant', '', '', '', '', 'fett wie ein Hydrant', '[{"kategorie": "", "text": "\"voll bis oben hin\""}, {"kategorie": "", "text": "besoffen bis unter die Haare"}, {"kategorie": "", "text": "blau wie ein Matrose"}, {"kategorie": "", "text": "[[fett]] wie eine Haubitzen"}, {"kategorie": "", "text": "[[fett]] wie ein Indianer"}]'::jsonb, ''),
  ('fett-wiara-oeoesadin', 'fett wiara Öösadin', '', '', '', '', 'fett wie eine Ölsardine', '[{"kategorie": "", "text": "\"voll bis oben hin\""}, {"kategorie": "", "text": "besoffen bis unter die Haare"}, {"kategorie": "", "text": "blau wie ein Matrose"}, {"kategorie": "", "text": "[[fett]] wie eine Haubitzen"}, {"kategorie": "", "text": "[[fett]] wie ein Indianer"}]'::jsonb, ''),
  ('i-bin-fett', 'I bin fett!', '', '', '', '', 'Ich bin fett!', '[{"kategorie": "wörtlich", "text": "Ich bin sternhagelvoll!“  2. (scherzhaft für): Ich bin voll wie eine Haubitze!  3. Ich bin stockbesoffen bis zum Anschlag!  4.[[I]] bin in da Fettn!  5. [[I]] bin im Öl!  6. (Deutschland): Ich bin hackedicht voll!"}]'::jsonb, ''),
  ('sei-fett-okriang', 'sei Fett okriang', '', '', '', '', 'sein Fett abkriegen', '[{"kategorie": "", "text": "einen Verweis bekommen"}, {"kategorie": "", "text": "einen Rüffel kassieren"}, {"kategorie": "", "text": "abgestraft werden (eine gerechte Strafe oder die verdiente Portion Kritik erhalten)"}]'::jsonb, ''),
  ('in-boin-mid-ana-fettn-schbueuen', 'in Boin mid ana Fettn schbüün', '', '', '', '', 'den Ball mit einer Fetten spielen', '[{"kategorie": "", "text": "den Ball mit viel Effet schießen"}, {"kategorie": "", "text": "dem Ball sehr viel Drall mitgeben"}]'::jsonb, ''),
  ('in-da-fettn-sei', 'in da Fettn sei', '', '', '', '', 'in der Fetten sein', '[{"kategorie": "wörtlich", "text": "\"im Vollrausch sein\""}, {"kategorie": "", "text": "\"voll bis oben hin sein\""}, {"kategorie": "", "text": "besoffen sein bis unter die Haare"}, {"kategorie": "", "text": "blau wie ein Matrose sein"}, {"kategorie": "", "text": "[[fett]] wie die russische Erde sein"}]'::jsonb, ''),
  ('waunn-i-in-da-fettn-bin-is-ma-ollas-powidl', 'Waunn I in da Fettn bin, is ma ollas Powidl!', '', '', '', '', 'Wenn ich in der Fetten bin, ist mir alles Powidl!', '[{"kategorie": "", "text": "Wenn ich im Vollrausch bin, ist mir alles schnurzpiepegal!  2. Im Vollrausch ist mir alles [[wurscht]]!  3. Im Vollrausch pfeife ich auf alles!"}]'::jsonb, ''),
  ('ea-hod-an-echtn-fettling-aun-laund-zoong', 'Ea hod an echtn Fettling aun Laund zoong!', '', '', '', '', 'Er hat einen echten Fettling an Land gezogen!', '[{"kategorie": "", "text": "Er hat einen dicken Auftrag an Land gezogen!  2. Er hat einen echt fetten Deal abgeschlossen!  3. Er hat einen wahren Hochkaräter an Land gezogen!"}]'::jsonb, ''),
  ('blaeaed-wiara-binkl-fetzn', 'blääd wiara Binkl Fetzn!', '', '', '', '', 'blöd wie ein Bündel Fetzen', '[{"kategorie": "scherzhaft für", "text": "\"dumm wie Stroh\""}, {"kategorie": "", "text": "strohdumm, saublöd, [[fetzndeppad]], [[angeschüttet]] wie ein Hydrant"}]'::jsonb, ''),
  ('deppad-wiara-binkl-fetzn', 'deppad wiara Binkl Fetzn!', '', '', '', '', 'deppert wie ein Bündel Fetzen', '[{"kategorie": "scherzhaft für", "text": "\"dumm wie Stroh\""}, {"kategorie": "", "text": "strohdumm, saublöd, [[fetzndeppad]], völlig daneben, [[angeschüttet]] wie ein Hydrant"}]'::jsonb, ''),
  ('dea-gheat-mid-an-nossn-fetzn-daschloong', 'Dea gheat mid an nossn Fetzn daschloong!', '', '', '', '', 'Der gehört mit einem nassen Fetzen erschlagen!', '[{"kategorie": "wörtlich", "text": "\"Der gehört so lange mit einem nassen Fetzen auf den Schädel geschlagen, bis er was tut!\"  2. Mit dem ist überhaupt nichts anzufangen"}, {"kategorie": "", "text": "Der ist zu überhaupt nichts nutze!"}]'::jsonb, ''),
  ('i-daschloog-di-mid-an-nossn-fetzn', 'I daschloog di mid an nossn Fetzn!', '', '', '', '', 'Ich erschlage dich mit einem nassen Fetzen!', '[{"kategorie": "wörtlich, schroffe Gewaltandrohung", "text": "\"Ich werde dich so lange mit einem nassen Fetzen auf den Schädel schlagen, bis du einen Kopf kürzer bist!\"  2. Ich haue dir gleich eins auf den Deckel!  3. Ich verpasse dir gleich eine Tracht Prügel!"}]'::jsonb, ''),
  ('do-feichdlts', 'Do feichdlts!', '', '', '', '', 'Da feuchtelt es', '[{"kategorie": "wörtlich", "text": "Hier ist es ordentlich feucht!  2. Hier steht die Luft vor Feuchtigkeit"}, {"kategorie": "", "text": "Do hods a uandliche [[Feichtn]]!"}]'::jsonb, ''),
  ('do-hods-a-uandliche-feichtn', 'Do hods a uandliche Feichtn!', '', '', '', '', 'Da hat es eine ordentliche Feuchte', '[{"kategorie": "wörtlich", "text": "Hier ist es ordentlich feucht!  2. Hier steht die Luft vor Feuchtigkeit"}, {"kategorie": "", "text": "Hier [[feuchtelt]] es in allen Ecken!"}]'::jsonb, ''),
  ('da-liawe-augustin', 'Da liawe Augustin', '', '', '', '', 'Der Liebe Augustin', '[{"kategorie": "wörtlich", "text": "\"Augustin N.\" (1645-1685, verewigt als \"Augustin-Denkmal\" am Augustinplatz im 7. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Wiener Bänkelsänger und Stadtoriginal (sein Vorname war stadtbekannt, seinen Nachnamen kannte niemand, also vermerkte der Totenbeschauer am 11. März 1685 im amtlichen Protokoll statt des Nachnemens den Großbuchstaben \"N.\" (=\"nescio\"=lat. für \"unbekannt\"): \"Augustin N., Sakhpfeiffer, ist auf freyer gassen in der Herren Gassen an der lungl beschaut, alt bey 40 jahr.)"}, {"kategorie": "", "text": "Wiener Sagengestalt (Der „Liebe Augustin“, wie er in der Sage genannt wird, soll im Jahr 1679 von den Pestknechten für tot gehalten worden sein, als er sich nach einer ausgiebigen Zechtour auf dem Heimweg befand. Sie warfen ihn in eine Pestgrube bei der Kirche St. Ulrich. Doch als er wieder Lebenszeichen von sich gab, wurde er herausgeholt und setzte sein ausschweifendes Leben wie bisher fort - so als wäre nichts geschehen)"}, {"kategorie": "", "text": "Inbegriff der Wiener Lebensart (d.h. Inbegriff dafür, dass man mit Humor alles überstehen kann)"}]'::jsonb, ''),
  ('augustin-liad', 'Augustin-Liad', '', '', '', '', 'Augustin-Lied', '[{"kategorie": "wörtlich", "text": "\"Das Lied vom Lieben Augustin\" (\"Oh du lieber Augustin, Augustin, Augustin, oh du lieber Augustin, alles ist hin!\")"}, {"kategorie": "", "text": "Wiener Ballade und Volkslied (wird dem \"Lieben Augustin\" zugeschrieben)"}, {"kategorie": "", "text": "Inbegriff der Wiener Lebensart (d.h. Inbegriff dafür, dass man mit Humor alles überstehen kann)"}]'::jsonb, ''),
  ('mei-klaane-fifi-maus', 'Mei klaane Fifi-Maus!', '', '', '', '', 'Meine kleine Fifi-Maus!', '[{"kategorie": "", "text": "Mein kleines, süßes Mäuschen!  2. Meine süße Herzallerliebste!  3. Meine kleine Prinzessin"}]'::jsonb, ''),
  ('draa-kan-fueuem', 'Draa kan Füüm!', '', '', '', '', 'Drehe keinen Film!', '[{"kategorie": "", "text": "Mach keine Szene!  2. Mach kein Theater!  3. Spiel dich nicht so auf!  4. Mach keinen Zirkus!"}]'::jsonb, ''),
