  ('nimm-de-klaeaewaen-weg-do', 'Nimm de Klääwän weg do!', '', '', '', '', 'Nimm die Kläweln weg da!', '[{"kategorie": "", "text": "Nimm deine Finger da weg!  2. Finger weg!  3. [[Geh]] weg mit den Fingern!"}]'::jsonb, ''),
  ('gee-weg-mid-deine-dreckichn-sauklaeaewaen', 'Gee weg mid deine dreckichn Sauklääwän!', '', '', '', '', 'Geh weg mit deinen dreckigen Saukläweln!', '[{"kategorie": "", "text": "Nimm deine dreckigen Saufinger da weg!  2. Weg mit den dreckigen Schmutzfingern!  3. Geh weg mit deinen dreckigen Schweineklauen!"}]'::jsonb, ''),
  ('muassd-du-deine-klaeaewaen-iwaroi-drin-haum', 'Muassd du deine Klääwän iwaroi drin haum?', '', '', '', '', 'Musst du deine Kläweln überall drin haben?', '[{"kategorie": "", "text": "Musst du überall deine Griffel reinstecken?  2. Musst du deine Würstelfinger überall reinstecken?"}]'::jsonb, ''),
  ('si-wos-ausd-finga-zuzln', 'si wos ausd Finga zuzln', '', '', '', '', 'sich etwas aus den Fingern zuzeln', '[{"kategorie": "", "text": "sich etwas aus den Fingern saugen"}, {"kategorie": "", "text": "sich etwas aus dem Blauen zusammenreimen"}, {"kategorie": "", "text": "etwas aus dem Nichts zusammenkleistern (die Wendung stammt womöglich aus einem alten Volksglauben, wonach jemandem durch das Saugen eines vorher in Blut oder eine Zauberflüssigkeit getauchten Fingers Weisheit vermittelt wird)"}]'::jsonb, ''),
  ('do-kaunnst-da-olle-zehn-finga-oschleckn', 'Do kaunnst da olle zehn Finga oschleckn!', '', '', '', '', 'Da kannst du dir alle zehn Finger abschlecken!', '[{"kategorie": "", "text": "Da kannst du echt froh sein!  2. Da kannst du dich wirklich glücklich schätzen!  3. Da hast du echt Schwein gehabt!"}]'::jsonb, ''),
  ('si-in-mittlfinga-geem', 'si in Mittlfinga geem', '', '', '', '', 'sich den Mittelfinger geben', '[{"kategorie": "", "text": "sich den Mittelfinger tief in den Rachen schieben, um zu erbrechen"}, {"kategorie": "", "text": "Brechreiz auslösen"}]'::jsonb, ''),
  ('geest-weg-mit-de-finga', 'Geest weg mit de Finga!', '', '', '', '', 'Geh weg mit den Fingern!', '[{"kategorie": "", "text": "Nimm deine Finger da weg!  2. Finger weg!  3. [[Nimm]] de Gläwän weg do!"}]'::jsonb, ''),
  ('zwischen-finsta-und-klostaneibuag', 'Zwischen finsta und Klostaneibuag!', '', '', '', '', 'Zwischen finster und Klosterneuburg!', '[{"kategorie": "", "text": "Irgendwann im nächsten Leben!  2. Auf ewig und drei Tage!  3. Am Sankt Nimmerleinstag!  4. [[Bis]] jó reggelt!"}]'::jsonb, ''),
  ('wia-sitzn-olle-in-da-finstan', 'Wia sitzn olle in da Finstan!', '', '', '', '', 'Wir sitzen alle in der Finstern', '[{"kategorie": "", "text": "Wir sitzen alle im Dunkeln!  2. Wir sitzen alle in der [[Stockfinstern]]!"}]'::jsonb, ''),
