  ('noch-wos-fipan', 'noch wos fipan', '', '', '', '', 'nach etwas fippern', '[{"kategorie": "wörtlich", "text": "\"nervös und aufgeregt nach etwas langen\" (vom mittelhochdeutschen \"fiebern\"=\"zappelig sein\")"}, {"kategorie": "fig.", "text": "sich sehr stark nach etwas sehnen, sich verzehren nach etwas, schmachten nach etwas"}]'::jsonb, ''),
  ('fressn-wiara-firmling', 'fressn wiara Firmling', '', '', '', '', 'fressen wie ein Firmling', '[{"kategorie": "wörtlich", "text": "\"sich den Bauch vollschlagen wie ein [[Firmling]]\""}, {"kategorie": "", "text": "fressen wie ein [[Scheunendrescher]], fressen wie ein [[Oberlehrer]], fressen wie ein [[Halterbub]], fressen wie ein [[Schinder]]"}]'::jsonb, ''),
  ('einehaun-wiara-firmling', 'einehaun wiara Firmling', '', '', '', '', 'reinhauen wie ein Firmling', '[{"kategorie": "wörtlich", "text": "\"sich den Bauch vollschlagen wie ein [[Firmling]]\""}, {"kategorie": "", "text": "fressen wie ein [[Scheunendrescher]], fressen wie ein [[Oberlehrer]], fressen wie ein [[Halterbub]], fressen wie ein [[Schinder]]"}]'::jsonb, ''),
  ('do-geed-ma-da-fisch-in-sock-auf', 'Do geed ma da Fisch in Sock auf!', '', '', '', 'Wiener Gaunersprache', 'Da geht mir der Fisch im Sack auf!', '[{"kategorie": "wörtlich", "text": "\"Da springt mir das Klappmesser im Hosensack auf (noch ehe ich es rausgezogen habe)!\"  2. (fig.) Da kocht mir das Blut über!  3. Da sehe ich rot!"}]'::jsonb, ''),
  ('do-geed-ma-da-fisch-in-da-hoosn-auf', 'Do geed ma da Fisch in da Hoosn auf!', '', '', '', 'Wiener Gaunersprache', 'Da geht mir der Fisch in der Hosen auf!', '[{"kategorie": "wörtlich", "text": "\"Da springt mir das Klappmesser im Hosensack auf (noch ehe ich es rausgezogen habe)!\"  2. (fig.) Da kocht mir gleich das Blut über!  3. Da sehe ich rot!"}]'::jsonb, ''),
  ('do-is-a-fisch-in-da-suppn', 'Do is a Fisch in da Suppn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da ist ein Fisch in der Suppe!', '[{"kategorie": "wörtlich", "text": "\"Da ist ein Haar in der Suppe!\" 2. (fig.) Da ist irgendwo der Wurm drin!  3. Da stimmt etwas nicht!  4. Da ist etwas im Busch!"}]'::jsonb, ''),
  ('an-fisch-zsaummdraan', 'an Fisch zsaummdraan', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Fisch zusammendrehen', '[{"kategorie": "wörtlich", "text": "\"einen Fehler fabrizieren\""}, {"kategorie": "", "text": "\"einen Fehler bauen\""}, {"kategorie": "", "text": "\"einen Bock schießen\""}, {"kategorie": "", "text": "\"einen Patzer machen\""}, {"kategorie": "", "text": "\"einen Missgriff tun\""}]'::jsonb, 'Da Bua hod beim Bruch an uandlichn Fisch zsaummdraad - ea is direkt bei da Kamera duachmaschiad!'),
  ('da-bua-hod-beim-bruch-an-uandlichn-fisch-zsaummdraad-ea-is-direkt-bei-da-kamera-duachmaschiad', 'Da Bua hod beim Bruch an uandlichn Fisch zsaummdraad - ea is direkt bei da Kamera duachmaschiad!', '', '', '', 'Wiener Gaunersprache', 'Der Bub hat beim Bruch einen ordentlichen Fisch zusammengedreht – er ist direkt bei der Kamera durchmarschiert!', '[{"kategorie": "wörtlich", "text": "\"Der Bub hat beim Einbruch einen ordentlichen Bock geschossen – er ist direkt bei der Kamera durchspaziert!\"  2. Der Junge hat beim Einbruch einen schweren Patzer gemacht - er ist direkt ins Kamerabild marschiert!  3. Der Bub hat einen kapitalen Bock gebaut – er ist direkt ins Sichtfeld der Kamera gelatscht!"}]'::jsonb, 'an Fisch zsaummdraan'),
  ('wos-auf-a-fischhoin-umpuudan', 'wos auf a Fischhoin umpuudan', '', '', '', '', 'etwas auf eine Fischhalle umpudern', '[{"kategorie": "wörtlich", "text": "\"etwas auf eine Fischhalle umbuttern\""}, {"kategorie": "scherzhaft für", "text": "etwas total umkrempeln"}, {"kategorie": "", "text": "etwas von Grund auf erneuern"}, {"kategorie": "", "text": "Tabula rasa machen und alles radikal ändern"}]'::jsonb, ''),
  ('fressn-wiara-aansa', 'fressn wiara Aansa', '', '', '', '', 'fressen wie ein Einser', '[{"kategorie": "wörtlich", "text": "\"fressen wie die Nummer eins\""}, {"kategorie": "fig.", "text": "sich den Bauch vollschlagen wie ein [[Firmling]]\""}, {"kategorie": "", "text": "fressen wie ein [[Scheunendrescher]]"}, {"kategorie": "", "text": "fressen wie ein [[Oberlehrer]]"}, {"kategorie": "", "text": "fressen wie ein [[Halterbub]]"}, {"kategorie": "", "text": "fressen wie ein [[Schinder]]"}]'::jsonb, ''),
  ('de-oide-hod-ia-jaummagschichd-so-oft-owabeet-dasssas-jetzt-woascheinlich-soeoewa-scho-glaubd', 'De Oide hod ia Jaummagschichd so oft owabeet, dasssas jetzt woascheinlich sööwa scho glaubd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Alte hat ihre Jammergeschichte so oft runtergebetet, dass sie sie jetzt wahrscheinlich selber schon glaubt!', '[{"kategorie": "wörtlich", "text": "\"Die Alte hat ihre Leidesstory so oft runtergeleiert, dass sie sie jetzt wohl selbst schon glaubt!\"  2. Die Alte hat ihren Selbstmitleidsroman so oft abgespult, dass sie ihn inzwischen wohl selber schon glaubt!  3. Die Alte labert ihre Leidensstory schon so lange runter, dass sie den Scheiß jetzt wahrscheinlich selbst schon für wahr hält!"}]'::jsonb, ''),
  ('i-muass-de-oide-tapeetn-owafetzn-damit-ma-neich-ausmoin-kenna', 'I muass de oide Tapeetn owafetzn, damit ma neich ausmoin kenna!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ich muss die alte Tapete runterfetzen, damit wir neu ausmalen können!', '[{"kategorie": "wörtlich", "text": "\"Ich muss die alte Tapete herunterreißen, damit wir neu ausmalen können!\"  2. Ich muss die alte Tapete entfernen, bevor wir die Wände neu streichen können!  3. Ich muss die alte Tapete erst runterreißen, bevor neue Farbe draufkann!"}]'::jsonb, ''),
  ('i-hob-in-aufsatz-in-zeen-minuten-owagfetzt-und-in-leara-hoda-sogoa-gfoin', 'I hob in Aufsatz in zeen Minuten owagfetzt - und in Leara hoda sogoa gfoin!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich habe den Aufsatz in zehn Minuten runtergefetzt - und dem Lehrer hat er sogar gefallen!', '[{"kategorie": "wörtlich", "text": "\"Ich habe den Aufsatz in zehn Minuten runtergerotzt - und dem Lehrer hat er sogar gefallen!\"  2. Ich hab den Aufsatz in zehn Minuten hingeknallt – und der Lehrer fand ihn auch noch gut!  3. Ich hab den Aufsatz in zehn Minuten  runtergekloppt – und der Lehrer hat''s gefressen!"}]'::jsonb, ''),
  ('dea-hockd-in-gaunzn-toog-vuam-kompjuta-und-fetzt-si-an-owa-home-office-sogda-dazua', 'Dea hockd in gaunzn Toog vuam Kompjuta und fetzt si an owa -''Home Office'' sogda dazua!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der hockt den ganzen Tag vorm Computer und schält sich einen runter – ''Homeoffice'' nennt er das dann!', '[{"kategorie": "wörtlich", "text": "\"Der hockt den ganzen Tag vorm PC und holt sich einen runter – nennt das dann Homeoffice!\"  2. Der glotzt den ganzen Tag auf seinen Bildschirm, wichst sich einen runter und nennt’s dann ''Arbeiten im Home Office''!\"  3. Der sitzt acht Stunden vorm Rechner, holt sich pausenlos einen runter und nennt das dann ''Homeoffice''!\""}]'::jsonb, ''),
  ('mit-dem-schdumpfn-messa-kaunnst-nua-no-feangln-kumm-hoi-in-schleifschdaa', 'Mit dem schdumpfn Messa kaunnst nua no feangln - kumm, hoi in Schleifschdaa!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Mit diesem stumpfen Messer kannst du nur noch ferngeln - komm, hol den Schleifstein!', '[{"kategorie": "wörtlich", "text": "\"Mit diesem stumpfen Messer kann man nur noch quetschschneiden - komm, hol den Schleifstein!\"  2. Das Messer ist so stumpf, dass man damit kaum noch sauber schneiden kann - bitte, hol den Schleifstein!  3. Mit so einem stumpfen Messer lässt''s sich nicht mehr sauber schneiden - hol mir bitte den Schleifstein!"}]'::jsonb, ''),
  ('wia-soi-i-mit-dem-schdumpfn-messa-a-scheim-brood-owafeangln-kumm-hoi-liawa-in-schleifschdaa', 'Wia soi I mit dem schdumpfn Messa a Scheim Brood owafeangln - kumm, hoi liawa in Schleifschdaa!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wie soll ich mit diesem stumpfen Messer eine Scheibe Brot runterferngeln - komm, hol lieber den Schleifstein!', '[{"kategorie": "wörtlich", "text": "\"Wie soll ich mit diesem stumpfen Messer eine Scheibe Brot runtersäbeln - komm, hol lieber den Schleifstein!\"  2. Das Messer ist so stumpf, dass man damit keine Scheibe Brot mehr runtersäbeln kann - bitte, hol lieber den Schleifstein!  3. Mit so einem stumpfen Messer lässt sich keine Schnitte Brot mehr sauber runterschneiden - hol mir bitte lieber den Schleifstein!"}]'::jsonb, ''),
  ('do-geeds-heit-oba-lustig-owa', 'Do geeds heit oba lustig owa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da geht''s heut aber lustig runter!', '[{"kategorie": "wörtlich", "text": "\"Da geht''s heut aber lustig zu!\"  2. Da ist heut aber echt was los!  3. Da geht heute ja echt was ab!  4. Da geht''s ja lustig runter heute!  5. Da geht ja heute richtig die Post ab!"}]'::jsonb, ''),
  ('na-gee-de-deppade-vinjetn-geed-ned-owa-von-da-scheim', 'Na gee, de deppade Vinjetn geed ned owa von da Scheim!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na geh, die depperte Vignette geht nicht runter von der Scheibe!', '[{"kategorie": "wörtlich", "text": "\"Na geh, die depperte Vignette lässt sich von der Scheibe nicht ablösen!\"  2. Verdammt, die blöde Autobahnvignette klebt so fest an der Scheibe, dass sie nicht runtergeht!  3. Verflixt, diese Scheißvignette hat sich so festgesaugt, dass sie nicht mehr runtergeht!"}]'::jsonb, ''),
  ('heast-wia-san-zu-viat-woi-ma-ned-an-gepflegtn-bauanschnopsa-owahaun', 'Heast, wia san zu viat - woi ma ned an gepflegtn Bauanschnopsa owahaun?', '', '', '', '', 'Hört mal, wir sind zu viert - wollen wir nicht einen gepflegten Bauernschnapser runterhauen?', '[{"kategorie": "wörtlich", "text": "\"Hört mal, wir sind zu viert - wollen wir nicht eine gepflegte Partie Bauernschnapsen runterspielen?\"  2. Hey, wir sind zu viert - wie wär''s mit einer kultivierten Runde Bauernschnapsen?  3. Hört mal, wird sind vier Leute - also klopfen wir doch einen kleinen Bauernschnapser runter!"}]'::jsonb, ''),
  ('si-woa-so-augfressn-dass-es-gaunze-gschia-vom-tisch-owaghaut-hod', 'Si woa so augfressn, dass es gaunze Gschia vom Tisch owaghaut hod!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie war so angefressen, dass sie das ganze Geschirr vom Tisch runtergehauen hat!', '[{"kategorie": "wörtlich", "text": "\"Sie war so angefressen, dass sie das ganze Geschirr vom Tisch runtergeschmissen hat!\"  2. Sie war so sauer, dass sie das ganze Geschirr vom Tisch runtergefegt hat!  3. Vor lauter Wut hat sie das Geschirr einfach vom Tisch runtergeschmissen!"}]'::jsonb, ''),
  ('wem-ane-owahaun', 'wem ane owahaun', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine runterhauen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine Watsche runterhauen\""}, {"kategorie": "", "text": "\"jemandem eine Ohrfeige verpassen\""}, {"kategorie": "", "text": "jemandem eine aufs Maul geben"}]'::jsonb, ''),
  ('waunn-dea-sei-goschn-ned-boid-hoid-hau-i-eam-aane-owe', 'Waunn dea sei Goschn ned boid hoid, hau I eam aane owe!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn der seine Goschen nicht bald hält, hau ich ihm eine runter!', '[{"kategorie": "wörtlich", "text": "\"Wenn der nicht bald den Mund hält, bekommt er von mir eine Ohrfeige!\"  2. Wenn der nicht bald die Fresse hält, kriegt er eine von mir reingeknallt!  3. Wenn er noch einmal den Mund aufmacht, pfeif ich ihm eine rein!"}]'::jsonb, 'wem ane owahaun'),
  ('de-haud-ian-oidn-scho-zeen-joa-laung-owa-und-puudad-si-duachn-gaunzn-bau', 'De haud ian Oidn scho zeen Joa laung owa und puudad si duachn gaunzn Bau!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die haut ihren Alten schon zehn Jahre lang runter und pudert sich durch den ganzen Bau!', '[{"kategorie": "wörtlich", "text": "\"Die betrügt ihren Alten schon zehn Jahre lang runter und vögelt sich durch den ganzen Gemeindebau!\"  2. Die bescheißt ihren Kerl schon seit zehn Jahren und lässt keinen im Bau aus!  3. Die betrügt ihren Mann schon seit zehn Jahren und hüpft wie ein Wanderpokal durch sämtliche Betten im Haus!"}]'::jsonb, ''),
  ('loss-di-ned-owahaun-nua-waeusd-nett-bist', 'Loss di ned owahaun, nua wäusd nett bist!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Lass dich nicht runterhauen, nur weil du nett bist!', '[{"kategorie": "wörtlich", "text": "\"Lass dich nicht übers Ohr hauen, nur weil du nett bist!\"  2. Lass dich nicht über den Tisch ziehen, nur weil du freundlich bist!  3. Lass dich nicht verarschen, nur weil du gutgläubig bist!"}]'::jsonb, ''),
  ('waunnst-da-dreimoi-aum-toog-an-owahaust-kriagst-krumme-finga', 'Waunnst da dreimoi aum Toog an owahaust, kriagst krumme Finga!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn du dir dreimal am Tag einen runterhaust, kriegst du krumme Finger!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dir dreimal am Tag einen runterholst, kriegst du krumme Finger!\"  2. Wenn du dreimal täglich wichst, kriegst du krumme Finger!  3. Bei dreimal täglich wichsen wird sich deine Hand bald zur Dauerfaust verkrampfen!"}]'::jsonb, ''),
  ('de-san-ins-toi-owakraeud-kumma-ois-waradns-aum-kilimandscharo-gweesn', 'De san ins Toi owakräud kumma, ois waradns aum Kilimandscharo gweesn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die sind ins Tal heruntergekrochen gekommen, als wären sie am Kilimandscharo gewesen!', '[{"kategorie": "wörtlich", "text": "Die sind da runtergetrottet gekommen, als wären sie gerade von einer Kilimandscharo-Expedition zurück!  2. So wie die da runtergekrabbelt kamen, hätte man denken können, sie wären am Kilimandscharo gewesen!  3. Als sie ins Tal runtergelatscht kamen, sahen sie aus, als hätten sie grad den Kilimandscharo barfuß und rückwärts erklommen!"}]'::jsonb, ''),
  ('ea-kraeud-ned-owa-von-seina-foadarung', 'Ea kräud ned owa von seina Foadarung!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Er kriecht nicht runter von seiner Forderung!', '[{"kategorie": "wörtlich", "text": "\"Er steigt nicht runter von seiner Forderung!\"  2. Er rückt nicht von seiner Forderung ab!  3. Was seine Forderung betrifft, so gibt er keinen Millimeter nach!"}]'::jsonb, ''),
  ('kraeu-owa', 'Kräu owa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kräul runter!', '[{"kategorie": "wörtlich", "text": "\"Kriech runter!\"  2. Bleib mir vom Leib!  3. Gib doch endlich Ruhe!"}]'::jsonb, ''),
  ('kraeu-ma-owa', 'Kräu ma owa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kräul mir runter!', '[{"kategorie": "wörtlich", "text": "\"Kriech runter von mir!\"  2. Bleib mir vom Leib!  3. Gib mir doch endlich Ruhe!"}]'::jsonb, ''),
  ('kraeu-oo', 'Kräu oo!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Kräul ab!', '[{"kategorie": "wörtlich", "text": "\"Kriech davon!\"  2. Hau ab!  3. Verschwinde!  4. [[Schleich]] di!  5. [[Putz]] di!  6. [[Draa]] di!  7. [[Mach]] Meter!  8. [[Gee]] päule!"}]'::jsonb, ''),
  ('ea-hod-in-breeslgeia-owaputzd-wiara-ausghungada-woif', 'Ea hod in Breeslgeia owaputzd wiara ausghungada Woif!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Er hat den Bröselgeier runtergeputzt wie ein ausgehungerter Wolf!', '[{"kategorie": "wörtlich", "text": "\"Er hat das Backhuhn weggeputzt wie ein ausgehungerter Wolf!\"  2. Er hat sich auf das panierte Huhn gestürzt wie ein ausgehungerter Wolf auf ein Lamm!  3. Er hat sich den Bröselgeier reingeschoben, als wär’s seine letzte Mahlzeit!"}]'::jsonb, ''),
  ('da-schaeaef-hod-mi-vua-olle-kolleegn-owaputzt-ois-war-i-a-schuibua', 'Da Schääf hod mi vua olle Kolleegn owaputzt, ois war I a Schuibua!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Chef hat mich vor allen Kollegen runtergeputzt, als wäre ich ein Schulbub!', '[{"kategorie": "wörtlich", "text": "\"Der Chef hat mich vor allen Kollegen runtergeputzt, als wäre ich ein Schuljunge!\"  2. Der Chef hat mich vor allen Kollegen zur Schnecke gemacht, als wäre ich ein kleiner Schüler!  3. Der Chef hat mich vor der ganzen Truppe runtergemacht, als wäre ich ein Praktikant im ersten Probemonat!"}]'::jsonb, ''),
  ('kenntast-bitte-endlich-des-gschia-vom-tisch-owaraaman', 'Kenntast bitte endlich des Gschia vom Tisch owaraaman?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Könntest du bitte endlich das Geschirr vom Tisch runterräumen?', '[{"kategorie": "wörtlich", "text": "\"Könntest du bitte endlich das Geschirr vom Tisch abräumen?\"  2. Wärst du so nett und räumst das Geschirr endlich vom Tisch runter?  3. Wie wär’s, wenn du das Geschirr langsam mal vom Tisch runterräumst?"}]'::jsonb, ''),
  ('bei-dem-deal-hoda-mea-owagraamd-ois-im-gaunzn-letztn-joa', 'Bei dem Deal hoda mea owagraamd ois im gaunzn letztn Joa!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Bei diesem Deal hat er mehr runtergeräumt als im ganzen letzten Jahr!', '[{"kategorie": "wörtlich", "text": "\"Bei diesem Deal hat er mehr Kohle gemacht als im ganzen letzten Jahr!\"  2. Mit diesem Deal hat er mehr verdient als im gesamten letzten Jahr!  3. Mit diesem Deal hat er mehr Geld gescheffelt als im ganzen letzten Jahr!"}]'::jsonb, ''),
  ('wem-s-wueuede-owaraaman', 'wem s''Wüüde owaraaman', '', '', '', 'Wiener Gaunersprache', 'jemandem das Wilde runterräumen', '[{"kategorie": "wörtlich", "text": "\"jemandem das Wilde austreiben\""}, {"kategorie": "", "text": "jemanden in die Schranken weisen"}, {"kategorie": "", "text": "jemandem die Flügel stutzen"}, {"kategorie": "", "text": "jemanden zurechtweisen, zurechtstutzen"}]'::jsonb, 'Dem Jungschbund weari des Wüüde scho no owaraaman - so laung, bisa waachkochd is!'),
  ('dem-jungschbund-weari-des-wueuede-scho-no-owaraaman-so-laung-bisa-waachkochd-is', 'Dem Jungschbund weari des Wüüde scho no owaraaman - so laung, bisa waachkochd is!', '', '', '', 'Wiener Gaunersprache', 'Dem Jungspund werde ich das Wilde schon noch runterräumen - so lange, bis er weichgekocht ist!', '[{"kategorie": "wörtlich", "text": "\"Dem Jungspund werde ich das Wilde schon noch austreiben - so lange, bis er weichgekocht ist!\"  2. Dem Kleinen werd ich das Aufmüpfige schon noch abgewöhnen - so lange, bis er weichgekocht ist!  3. Dem Rotzlöffel werde ich die Flausen schon noch austreiben – bis er zahm wie ein Lamm ist!"}]'::jsonb, 'wem s''Wüüde owaraaman'),
  ('de-raadld-ia-vakaufsmaschn-owa-ois-haedads-an-knopf-im-uawaschl', 'De raadld ia Vakaufsmaschn owa, ois hädads an Knopf im Uawaschl!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die radelt ihre Verkaufsmasche runter, als hätte sie einen Knopf im Ohrwaschel!', '[{"kategorie": "wörtlich", "text": "\"Die spult ihre Verkaufsmasche runter, als hätte sie einen Knopf im Ohr!\"  2. Die leiert ihren Verkaufsspruch runter wie eine Telefonhotline!  3. Die kotzt ihr Verkaufsskript runter, als wär sie ferngesteuert!"}]'::jsonb, ''),
  ('da-pforra-hod-in-bibltext-owagraatscht-wiaran-wettabericht-aus-da-hoeoe', 'Da Pforra hod in Bibltext owagraatscht wiaran Wettabericht aus da Höö!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Der Pfarrer hat den Bibeltext runtergeratscht wie einen Wetterbericht aus der Hölle!', '[{"kategorie": "wörtlich", "text": "\"Der Pfarrer hat den Bibeltext runtergebetet wie einen Wetterbericht aus der Hölle!\"  2. Der Pfarrer hat seine Predigt runtergeleiert wie ein Synchronsprecher aus der Hölle!  3. Gott hat die Welt in 7 Tagen erschaffen – dieser Pfarrer hat die Predigt in 5 Minuten heruntergeratscht!"}]'::jsonb, ''),
  ('bevua-ma-de-traum-eikochn-miass-mas-no-owaraeaewaen', 'Bevua ma de Traum eikochn, miass mas no owarääwän!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Bevor wir die Trauben einkochen, müssen wir sie noch runterrebeln!', '[{"kategorie": "wörtlich", "text": "\"Bevor wir die Trauben einkochen, müssen wir sie noch abrebeln!\"  2. Bevor wir die Trauben einkochen, müssen wir sie noch von den Stielen trennen!  3. Die Trauben müssen vor dem Einkochen noch von den Rispen gelöst werden!"}]'::jsonb, ''),
  ('de-baeaend-hod-ian-hit-volle-waesch-owagraeaewaed', 'De Bäänd hod ian Hit volle Wäsch owagrääwäd!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Die Band hat ihren Hit volle Wäsch runtergerebelt!', '[{"kategorie": "wörtlich", "text": "\"Die Band hat ihren Hit mit voller Wucht runtergerockt!\"  2. Die Band hat ihren Hit mit voller Energie rausgehauen!  3. Die Band hat ihren Hit derart von der Bühne runtergefeuert, dass der Boden gebebt hat!"}]'::jsonb, ''),
  ('seit-sei-oide-auszoong-is-muassa-si-soeoewa-an-owaraeaewaen', 'Seit sei Oide auszoong is, muassa si sööwa an owarääwän!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit seine Alte ausgezogen ist, muss er sich selbst einen runterrebeln!', '[{"kategorie": "wörtlich", "text": "\"Seit seine Alte ausgezogen ist, muss er sich halt selbst einen herunterholen!\"  2. Seit seine Alte das Weite gesucht hat, muss er sich die Nudel selbst polieren!  3. Seit seine Alte abgedampft ist, wichst er sich die Einsamkeit allein aus dem Sack!"}]'::jsonb, ''),
  ('da-bua-is-in-vooda-wia-owegrissn', 'Da Bua is in Vooda wia owegrissn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Der Bub ist dem Vater wie runtergerissen!', '[{"kategorie": "wörtlich", "text": "\"Der Bub ist dem Vater wie aus dem Gesicht geschnitten!\"  2. Man braucht keine DNA-Probe – der Bub ist eine 1:1-Kopie seines Vaters!  3. Der Bub ist ein Ebenbild vom Papa!  4. Das ist kein Sohn, das ist ein Klon!"}]'::jsonb, ''),
  ('reiss-owa-in-vabaund', 'Reiss owa in Vabaund!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Reiß runter den Verband!', '[{"kategorie": "wörtlich", "text": "\"Mach den Verband ab!\"  2. Runter mit dem Verband!  3. Ab mit dem alten Drecksverband!"}]'::jsonb, ''),
  ('dea-sitzd-in-gaunzn-toog-im-zimma-und-reissd-si-an-owa', 'Dea sitzd in gaunzn Toog im Zimma und reissd si an owa!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der sitzt den ganzen Tag im Zimmer und reißt sich einen runter!', '[{"kategorie": "wörtlich", "text": "\"Der sitzt den ganzen Tag im Zimmer und holt sich einen runter!\"  2. Der hängt daheim ab und onaniert den ganzen Tag!  3. Der sitzt den ganzen Tag im Zimmer und wichst sich durchs Leben!"}]'::jsonb, ''),
  ('bevuasd-in-opfae-issd-tua-bitte-de-schoin-owaschoeoen-dea-is-naemlich-gschbritzd', 'Bevuasd in Opfä issd, tua bitte de Schoin owaschöön - dea is nämlich gschbritzd!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Bevor du den Apfel isst, tu bitte erst die Schale runterschälen – der ist nämlich gespritzt!', '[{"kategorie": "wörtlich", "text": "\"Bevor du den Apfel isst, schäl bitte erst die Schale runter – der ist nämlich gespritzt!\"  2. Schäl den Apfel lieber erst, bevor du ihn isst – der wurdee behandelt!  3. Bitte den Apfel vorher schälen – er ist mit Pflanzenschutzmitteln behandelt worden!"}]'::jsonb, ''),
  ('waunn-ma-faad-is-schoeoe-i-ma-an-owa-so-vageed-a-de-zeit', 'Waunn ma faad is, schöö I ma an owa - so vageed a de Zeit!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wenn mir fad ist, schäl ich mir einen runter - so vergeht auch die Zeit!', '[{"kategorie": "wörtlich", "text": "\"Wenn mir langweilig ist, hol ich mir einen runter - so vergeht auch die Zeit!\"  2. Wenn ich vor lauter Langeweile nichts mehr mit mir anzufangen weiß, wichse ich mir einen runter - besser als nix!  3. Wenn die Zeit schleicht, eröffne ich meinen Ein-Mann-Zirkus und hol mir einen runter - besser als nix!"}]'::jsonb, ''),
  ('himmaevoodaa-schau-owa', 'Himmävoodaa, schau owa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Himmelvater, schau runter!', '[{"kategorie": "wörtlich", "text": "\"Oh Himmelvater, öffne deine Augen!\" (emotional gefärbter, volkstümlicher Ausruf, der Gott als höhere Instanz anruft)"}, {"kategorie": "", "text": "Allmächtiger, steh uns bei!  3. Herr im Himmel, erbarme dich unser!  4. Du lieber Himmel, das ist ja niicht normal!  5. Ein Wahnsinn - da hilft nur noch göttlicher Beistand!  6. Himmelvater, mach die Augen auf und hilf!  7. Heiliger Himmel, was für ein Schauspiel!"}]'::jsonb, ''),
  ('si-hoid-si-fia-de-keenigin-und-schaud-auf-uns-olle-owa-wia-aufs-fuassvoik', 'Si hoid si fia de Keenigin und schaud auf uns olle owa wia aufs Fuassvoik!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie hält sich für die Königin und schaut auf uns alle runter wie aufs Fußvolk!', '[{"kategorie": "wörtlich", "text": "\"Sie hält sich für die Queen und schaut auf uns alle herab wie aufs Fußvolk!\"  2. Sie denkt, sie wär was Besseres und behandelt uns wie Menschen zweiter Klasse!  3. Madame hält sich für den Nabel der Welt – und wir sind das graue Hintergrundrauschen!"}]'::jsonb, ''),
  ('tua-ma-de-kraxn-easchd-amoi-zua-weakstott-owascheibm', 'Tua ma de Kraxn easchd amoi zua Weakstott owascheibm!', '', '', '', 'Wiener Mechaniker-Slang', 'Tun wir die Kraxen erst einmal zur Werkstatt runterscheiben!', '[{"kategorie": "wörtlich", "text": "\"Lass uns die Karre erst mal zur Werkstatt runterschieben!\"  2. Schieben wir die Kiste erst mal zur Werkstatt runter, bevor sie ganz auseinanderfällt!  3. Komm, schieben wir den Schrottkarren erst mal runter zur Werkstatt, bevor er uns unterm Hintern explodiert!"}]'::jsonb, ''),
  ('wuevueue-schdund-muassd-heid-no-owascheibm-bisd-frei-host', 'Wüvüü Schdund muassd heid no owascheibm, bisd frei host?', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wie viele Stunden musst du heut noch runterscheiben, bis du frei hast?', '[{"kategorie": "wörtlich", "text": "\"Wie viele Stunden musst du heut noch runterschieben, bis du frei hast?\"  2. Wie viele Stunden musst du heute noch abdienen, bis du Feierabend hast?  3. Wie viele Sklavenstunden hast du heute noch, bevor du wieder leben darfst?"}]'::jsonb, ''),
  ('a-joa-muass-i-no-owascheibm-daunn-deaf-i-s-easchde-moi-um-a-hoiwe-ausuachn', 'A Joa muass I no owascheibm, daunn deaf I s''easchde Moi um a Hoiwe ausuachn!', '', '', '', 'Wiener Gaunersprache', 'Ein Jahr muss ich noch runterscheiben, dann darf ich das erste Mal um eine Halbe ansuchen!', '[{"kategorie": "wörtlich", "text": "\"Ein Jahr muss ich noch runterschieben, dann darf ich das erste Mal um eine bedingte Haftentlassung nach Verbüßung der Hälfte der Strafe ansuchen!\"  2. Ich muss noch ein Jahr absitzen, dann kann ich erstmals einen Antrag auf vorzeitige Entlassung stellen!  3. Noch ein Jahr hinter Gittern – dann kommt vielleicht der goldene Brief!"}]'::jsonb, ''),
  ('schdeig-owa-von-dein-hochn-ross-bevua-da-do-oom-no-de-luft-ausgeed', 'Schdeig owa von dein hochn Ross, bevua da do oom no de Luft ausgeed!', '', '', '', 'Wiener Gaunersprache', 'Steig runter von deinem hohen Ross, bevor dir da oben noch die Luft ausgeht!', '[{"kategorie": "wörtlich", "text": "\"Steig runter von deinem hohen Ross, bevor''s noch ganz dünn mit dem Sauerstoff da oben wird!\"  2. Komm runter von deinem hohen Ross, noch bevor es dich gleich abwirft!  3. Steig lieber freiwillig ab, bevor ich dich noch von deinem hohen Ross runterhol!"}]'::jsonb, ''),
  ('da-wuchara-schdeigd-kan-cent-owa-von-seine-zwanzg-prozent-do-geed-nix', 'Da Wuchara schdeigd kan Cent owa von seine zwanzg Prozent - do geed nix!', '', '', '', 'Wiener Gaunersprache', 'Der Wucherer steigt keinen Cent runter von seinen zwanzig Prozent - da geht nix!', '[{"kategorie": "wörtlich", "text": "\"Der Kredithai steigt keinen Cent von seinen zwanzig Prozent runter - da ist nichts zu machen!\"  2. Der Blutsauger rückt keinen Cent von seinen zwanzig Prozent ab - da ist nichts zu holen!  3. Der Geldverleiher weicht keinen Millimeter von seinen Wucherzinsen ab – verhandeln unmöglich!"}]'::jsonb, ''),
  ('dea-schdeigt-ma-ned-owa', 'Dea schdeigt ma ned owa!', '', '', '', 'Wiener Gaunersprache', 'Der steigt mir nicht runter', '[{"kategorie": "wörtlich", "text": "\"Der rückt mir nicht von der Pelle!\"  2. Er hört nicht auf, mich zu drangsalieren!  3. Er rückt mir nicht vom Leib!  4. Er lässt mich nicht in Frieden!"}]'::jsonb, ''),
  ('es-hod-deamaasn-owagwaschld-dass-da-plotz-drei-toog-unbeschbueueboa-woa', 'Es hod deamaasn owagwaschld, dass da Plotz drei Toog unbeschbüüboa woa!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Es hat dermaßen runtergewaschelt, dass der Platz drei Tage unbespielbar war!', '[{"kategorie": "wörtlich", "text": "\"Es hat runtergeschüttet wie aus Kübeln - der Platz war ganze drei Tage lang unbespielbar!\"  2. Es hat runtergeregnet wie aus Eimern, bis der Platz aussah wie ein Schlammbad!  3. Der Regen hat dermaßen runtergeprügelt, dass der Platz drei Tage lang unbespielbar war und einer Sumpfwüste glich!\""}]'::jsonb, ''),
  ('obwoi-i-in-wei-gaunz-laungsaum-owazipfae-wiara-pforra-beim-frueueschoppn-sans-aum-schluss-trotzdem-imma-sechs-viatln', 'Obwoi I in Wei gaunz laungsaum owazipfä wiara Pforra beim Früüschoppn, sans aum Schluss trotzdem imma sechs Viatln!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Obwohl ich den Wein ganz langsam runterzipfle wie ein Pfarrer beim Frühschoppen, sind es am Schluss trotzdem immer sechs Vierterln!', '[{"kategorie": "wörtlich", "text": "\"Obwohl ich den Wein im Schneckentempo runternipple wie ein Pfarrer beim Frühschoppen, sind es am Schluss trotzdem immer sechs Vierterln!\"  2. Ich trink den Wein zwar ganz langsam wie ein Pfarrer beim Frühschoppen, aber am Ende sind’s trotzdem sechs Vierterln!  3. Ich zieh mir den Wein zwar Schluck für Schluck rein, aber immer erst nach dem sechsten Viertel hör ich’s glockenläuten!"}]'::jsonb, ''),
  ('bis-dea-seine-schuidn-owazipfaed-hod-gibts-viilleicht-kan-euro-mea', 'Bis dea seine Schuidn owazipfäd hod, gibts viilleicht kan Euro mea!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bis der seine Schulden runtergezipfelt hat, gibt''s vielleicht keinen Euro mehr!', '[{"kategorie": "wörtlich", "text": "\"Bis der seine Schulden abgestottert hat, gibt''s wahrscheinlich keinen Euro mehr!\"  2. Bis der seine Schulden abgedrückt hat, ist der Euro vielleicht schon abgeschafft!  3. Bis der seine Schulden abbezahlt hat, ist die Eurowährung wohl nur noch Altpapier!"}]'::jsonb, ''),
  ('friara-hob-i-ma-beim-owaklaeaezln-von-da-vinjettn-imma-de-finganaeaegl-oobrochn', 'Friara hob I ma beim Owaklääzln von da Vinjettn imma de Finganäägl oobrochn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Früher hab ich mir beim Herunterkletzeln der Vignette immer die Fingernägel abgebrochen!', '[{"kategorie": "wörtlich", "text": "\"Früher hab ich mir beim Ablösen der Autobahnvignette immer die Fingernägel abgebrochen!\"  2. Früher waren alle meine Fingernägel abgebrochen, ehe ich die Vignette endlich von der Windschutzscheibe hatte!  3. Wenn ich - so wie früher - auch heute noch die Vignette von der Scheibe runterkletzeln müsste, hätte ich keine Fingernägel mehr!"}]'::jsonb, ''),
  ('si-hod-ma-a-reife-kiaschn-vom-ost-owazupfd-und-aus-iara-haund-direkt-in-mein-mund-foin-lossn', 'Si hod ma a reife Kiaschn vom Ost owazupfd und aus iara Haund direkt in mein Mund foin lossn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie hat mir eine reife Kirsche vom Ast runtergezupft und aus ihrer Hand direkt in meinen Mund fallen lassen!', '[{"kategorie": "wörtlich", "text": "\"Sie pflückte eine reife Kirsche vom Baum und ließ sie mir aus der Hand direkt in den Mund gleiten!\"  2. Sie pflückte mir eine sonnenwarme Kirsche vom Zweig und ließ sie mir wie eine süße Beute in den Mund gleiten!  3. Mit einem sanften Griff löste sie die Kirsche vom Zweig und ließ sie mir wie selbstverständlich in den Mund gleiten!"}]'::jsonb, ''),
  ('hobds-a-freindin-fia-mi-i-wueue-ma-ned-jedn-toog-soeoewa-an-owazupfn-miassn', 'Hobds a Freindin fia mi - I wüü ma ned jedn Toog sööwa an owazupfn miassn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Habt ihr eine Freundin für mich - ich will mir nicht jeden Tag selber einen runterzupfen müssen!', '[{"kategorie": "wörtlich", "text": "\"Habt ihr eine Freundin für mich - ich will mir nicht jeden Tag selber einen runterwichsen müssen!\"  2. Habt''s vielleicht ''ne Freundin für mich - ich will mich nicht ständig selbst befriedigen müssen!  3. Habt ihr vielleicht eine Freundin für mich - meine rechte Hand bräuchte dringend Urlaub!"}]'::jsonb, ''),
  ('ane-oobeedln', 'ane oobeedln', '', '', '', '', 'eine abbetteln', '[{"kategorie": "", "text": "um eine Ohrfeige betteln"}, {"kategorie": "", "text": "eine Ohrfeige provozieren"}]'::jsonb, ''),
  ('si-oobeidln', 'si oobeidln', '', '', '', '', 'sich abbeuteln', '[{"kategorie": "", "text": "sich abschütteln, durchschütteln"}, {"kategorie": "", "text": "sich nicht aus der Ruhe bringen lassen"}, {"kategorie": "", "text": "cool bleiben"}]'::jsonb, ''),
  ('si-obrausn-kenna', 'si obrausn kenna', '', '', '', '', 'sich abbrausen können', '[{"kategorie": "", "text": "sich etwas abschminken können"}, {"kategorie": "", "text": "sich etwas aus dem Kopf schlagen können"}]'::jsonb, ''),
  ('wem-oblitzn-lossn', 'wem oblitzn lossn', '', '', '', '', 'jemanden abblitzen lassen', '[{"kategorie": "", "text": "jemandem eine Abfuhr erteilen"}, {"kategorie": "", "text": "jemandem einen Korb geben"}, {"kategorie": "", "text": "[[wem]] wos moin"}, {"kategorie": "", "text": "[[wem]] de Gurkn geem"}]'::jsonb, ''),
  ('si-an-oobrechn', 'si an oobrechn', '', '', '', '', 'sich einen abbrechen', '[{"kategorie": "", "text": "sich krumm und bucklig lachen, [[sich]] abhauen, [[sich]] abpecken"}, {"kategorie": "", "text": "sich kringeln vor Lachen, sich schieflachen"}]'::jsonb, ''),
  ('si-obrennan-lossn', 'si obrennan lossn', '', '', '', '', 'sich abbrennen lassen', '[{"kategorie": "", "text": "sich von der Sonne bräunen lassen"}, {"kategorie": "", "text": "sich sonnen, sich bräunen"}]'::jsonb, ''),
  ('si-oobreesln', 'si oobreesln', '', '', '', '', 'sich abbröseln', '[{"kategorie": "wörtlich", "text": "\"sich krumm und bucklig lachen\" (vom mittelhochdeutschen \"brēsen\"=\"bröckeln\")"}, {"kategorie": "scherzhaft für", "text": "[[sich]] zerbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen, [[sich]] abbären"}]'::jsonb, ''),
  ('si-oobaean', 'si oobäan', '', '', '', '', 'sich abbären', '[{"kategorie": "wörtlich", "text": "\"auf der Bahre liegen vor Lachen\" (vom mittelhochdeutschen \"baere\"=\"Bahre\")"}, {"kategorie": "scherzhaft für", "text": "sich krumm und bucklig lachen, [[sich]] zerbröseln, [[sich]] abhauen, [[sich]] abpecken, [[sich]] einen Ast lachen"}]'::jsonb, ''),
  ('si-oobreckln', 'si oobreckln', '', '', '', '', 'sich abbröckeln', '[{"kategorie": "", "text": "sich krumm und bucklig lachen, [[sich]] abbröseln, [[sich]] abhauen, [[sich]] abpecken"}, {"kategorie": "", "text": "sich kringeln vor Lachen, sich schieflachen"}]'::jsonb, ''),
  ('si-oobiaschtn', 'si oobiaschtn', '', '', '', '', 'sich abbürsten', '[{"kategorie": "", "text": "sich abputzen"}, {"kategorie": "", "text": "die Verantwortung für etwas von sich weisen"}]'::jsonb, ''),
  ('dea-tuad-a-kriagl-owebuchsn-ois-warads-wossa', 'Dea tuad a Kriagl owebuchsn ois warads Wossa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der tut ein Krügerl runterbüchsen, als wär''s Wasser!', '[{"kategorie": "wörtlich", "text": "\"Der kippt ''ne Halbe Bier runter, als wär''s Wasser!\"  2. Der zieht sich das Bier rein wie Limo!  3. Der pfeift sich die Halbe runter, als wär’s Apfelsaft!"}]'::jsonb, ''),
  ('i-woa-so-fett-dass-i-de-koellaschdiang-kopfiwa-owegfoin-bin-owa-unkraut-vageed-ned', 'I woa so fett, dass I de Köllaschdiang kopfiwa owegfoin bin - owa Unkraut vageed ned!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich war so fett, dass ich die Kellerstiege kopfüber hinuntergefallen bin - aber Unkraut vergeht nicht!', '[{"kategorie": "wörtlich", "text": "\"Ich war so sternhagelvoll, dass ich die Kellerstiege kopfüber hinuntergefallen bin - aber Unkraut vergeht nicht!\"  2. Ich war so betrunken, dass ich die Kellertreppe runtergerollt bin – aber nix passiert, ich bin zäh wie Leder!  3. Ich war so voll, dass ich die Kellertreppe kopfüber runtergesegelt bin wie ein betrunkener Engel – aber ich leb noch, keine Sorge!"}]'::jsonb, ''),
  ('do-foit-da-de-lood-owe', 'Do foit da de Lood owe!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da fällt dir die Lade runter!', '[{"kategorie": "Ausdruck der Fassungslosigkeit", "text": "\"Da fällt dir die Kinnlade runter!\"  2. Da klappt die der Unterkiefer runter!  3. Da bleibt einem vor lauter Staunen der Mund offen!"}]'::jsonb, ''),
  ('do-foit-an-ollas-owe', 'Do foit an ollas owe!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da fällt einem alles runter!', '[{"kategorie": "Ausdruck der Fassungslosigkeit", "text": "\"Da bleibt einem fast das Herz stehen!\"  2. Da denkt man, die Welt geht unter!  3. Da ist man wie gelähmt!  4. Da zieht’s einem den Boden unter den Füßen weg!"}]'::jsonb, ''),
  ('do-leegst-di-niida', 'Do leegst di niida!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da legst dich nieder!', '[{"kategorie": "Ausdruck der Fassungslosigkeit", "text": "\"Das haut den stärksten Ochsen um!\"  2. Da zieht’s einem den Boden unter den Füßen weg!\"  3. Da fällt dir die Kinnlade bis zum Boden!  4. Ich glaub, ich spinne!  5. Das ist ja der helle Wahnsinn!  6. Da muss man sich vor Schreck erstmal setzen!  7. Das darf doch nicht wahr sein!  8. [[Heilige]] Scheiße!"}]'::jsonb, 'Pfiad di Good, Lackal!'),
  ('do-brauchst-ned-oweglengan', 'Do brauchst ned oweglengan!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Da brauchst du nicht runterlangen!', '[{"kategorie": "wörtlich", "text": "\"Da brauchst du erst gar nicht hinlangen!\"  2. Das kannst du dir sparen!  3. Schenk dir den Versuch!"}]'::jsonb, ''),
  ('si-owegoogln', 'si owegoogln', '', '', '', 'Wiener Kartentipplerjargon', 'sich owegogeln', '[{"kategorie": "wörtlich", "text": "\"sich runtergaukeln\" (Kompositum aus dem abtrennbaren Präfix [[owe]]=\"abhin\" und [[gogeln]]=\"gaukeln\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"sich hinuntergaukeln\", \"sich beim Schnapsen einen Punkt nach dem anderen runterschreiben\", \"sich Punkt für Punkt dem Sieg nähern\""}]'::jsonb, ''),
  ('ea-woa-scho-auf-an-aansa-oba-daunn-hob-i-mi-owegoogld-und-olle-restlichn-partiin-gwunnan', 'Ea woa scho auf an Aansa, oba daunn hob I mi owegoogld und olle restlichn Partiin gwunnan!', '', '', '', 'Wiener Kartentipplerjargon', 'Er war schon auf einem Einser, aber dann hab ich mich runtergegogelt und alle restlichen Partien gewonnen!', '[{"kategorie": "wörtlich, àSchnapsen", "text": "\"Er brauchte nur noch einen Punkt, aber dann hab ich mich runtergegaukelt und alle restlichen Partien gewonnen!\"  2. Ich war eigentlich schon raus – aber dann hab ich mich Punkt für Punkt runtergespielt zum Sieg!  3. Ein einziger Punkt hat ihm noch zum Sieg gefehlt - aber dann hab ich mich Punkt für Punkt runtergespielt und ihm am Schluss sogar noch besiegt!"}]'::jsonb, 'si owegoogln'),
  ('kaunnst-de-hazung-a-weng-owedraan', 'Kaunnst de Hazung a weng owedraan?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kannst du die Heizung ein wenig runterdrehen?', '[{"kategorie": "wörtlich", "text": "\"Würdest du die Heizung bitte etwas zurückdrehen?\"  2. Dreh die Heizung doch etwas runter!  3. Kannst du die Heizung etwas runterregeln?"}]'::jsonb, ''),
  ('i-tua-ma-echt-schwea-dass-i-de-zeit-iagendwia-sinnvoi-owedraa', 'I tua ma echt schwea, dass I de Zeit iagendwia sinnvoi owedraa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich tu mir echt schwer, dass ich die Zeit irgendwie sinnvoll runterdreh!', '[{"kategorie": "wörtlich", "text": "\"Ich tu mir echt schwer, die Zeit irgendwie sinnvoll runterlaufenen zu lassen!\"  2. Ich finde es wirklich schwierig, die Zeit irgendwie sinnvoll zu nutzen!  3. Ich weiß echt nicht, wie ich die Zeit sinnvoll rumkriegen soll!"}]'::jsonb, ''),
  ('de-konkurrenz-hod-eam-owedraad-bisa-kan-anzign-auftroog-mea-kriagd-hod', 'De Konkurrenz hod eam owedraad, bisa kan anzign Auftroog mea kriagd hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Konkurrenz hat ihn runtergedreht, bis er keinen einzigen Auftrag mehr gekriegt hat!', '[{"kategorie": "wörtlich", "text": "\"Die Konkurrenz hat ihn systematisch benachteiligt, bis ihm sämtliche Aufträge entzogen wurden!\"  2. Die Mitbewerber haben ihn so weit ausgebootet, dass er letztlich ohne Aufträge dastand!  3. Die Konkurrenz hat ihn eiskalt abserviert – und am Ende stand er ohne einen einzigen Auftrag da!"}]'::jsonb, ''),
  ('foa-ma-owi-noch-italiin', 'Foa ma owi noch Italiin!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fahren wir runter nach Italien!', '[{"kategorie": "wörtlich", "text": "\"Fahren wir runter gen Süden – nach Italien!\"  2. Lass uns runter nach Italien düsen!  3. Komm, wir machen einen Abflug runter nach Italien!"}]'::jsonb, ''),
  ('foa-ma-auffi-noch-deitschlaund', 'Foa ma auffi noch Deitschlaund!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fahren wir rauf nach Deutschland!', '[{"kategorie": "wörtlich", "text": "\"Fahren wir rauf gen Norden – nach Deutschland!\"  2. Lass uns rauf nach Deutschland düsen!  3. Komm, wir machen einen Abflug rauf nach Deutschland!"}]'::jsonb, ''),
  ('foa-in-blechtrottl-amoi-owi-und-daunn-wiida-auffi-viilleicht-rennd-daunn-s-weakl', 'Foa in Blechtrottl amoi owi und daunn wiida auffi - viilleicht rennd daunn s''Weakl!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Fahr den Blechtrottel einmal runter und dann wieder rauf - vielleicht rennt dann das Werkel!', '[{"kategorie": "wörtlich", "text": "\"Fahr den Computer einmal runter und dann wieder rauf - vielleicht fängt er sich dann!\"  2. Mach das Werkel aus und wieder an - vielleicht läuft der Blechtrottel dann!  3. Fahr die Blechkiste mal runter und wieder hoch – vielleicht funktioniert’s dann!"}]'::jsonb, ''),
  ('pass-auf-de-leita-woogld-fliag-ned-owa', 'Pass auf, de Leita woogld - fliag ned owa!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Pass auf, die Leiter wackelt - flieg nicht runter!', '[{"kategorie": "wörtlich", "text": "„Achtung, die Leiter wackelt – pass auf, dass du nicht runterfällst!“  2. Vorsicht, die Leiter wackelt –  stürz mir nicht ab!  3. Festhalten! Gleich kippt die Leiter – nicht runterfallen!"}]'::jsonb, ''),
  ('fliang-ma-owi-noch-italiin', 'Fliang ma owi noch Italiin!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fliegen wir runter nach Italien!', '[{"kategorie": "wörtlich", "text": "\"Fliegen wir runter gen Süden – nach Italien!\"  2. Lass uns runter nach Italien düsen!  3. Komm, wir machen einen Abflug runter nach Italien!"}]'::jsonb, ''),
  ('in-da-politik-fliagst-ned-ausse-sondan-auffi-egal-wia-deppadst-bist', 'In da Politik fliagst ned ausse, sondan auffi - egal wia deppadst bist!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In der Politik fliegst du nicht raus, sondern rauf - egal wie deppert du bist!', '[{"kategorie": "wörtlich", "text": "\"In der Politik fliegt man nicht raus, sondern immer höher nach oben - egal wie blöd man ist!\"  2. Wer in der Politik versagt, fliegt nicht raus, sondern rauf – egal welche Fehler er macht!  3. Politiker fliegen wie Federn – aber leider immer nach oben!"}]'::jsonb, ''),
  ('fliang-ma-auffi-noch-deitschlaund', 'Fliang ma auffi noch Deitschlaund!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fliegen wir rauf nach Deutschland!', '[{"kategorie": "wörtlich", "text": "\"Fliegen wir rauf gen Norden – nach Deutschland!\"  2. Lass uns rauf nach Deutschland düsen!  3. Komm, wir machen einen Abflug rauf nach Deutschland!"}]'::jsonb, ''),
  ('de-trottln-haum-3-0-gfiad-und-de-partii-trotzdem-no-owiglaad', 'De Trottln haum 3:0 gfiad und de Partii trotzdem no owiglaad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Trotteln haben 3:0 geführt und die Partie trotzdem noch runtergeleert!', '[{"kategorie": "wörtlich", "text": "\"Die Trotteln haben 3:0 geführt und die Partie trotzdem noch hergegeben!\"  2. Bei 3:0 hätten man das Spiel nur noch heimtragen müssen - aber die Trotteln haben es vergeigt!  3. Nach einem 3:0-Vorsprung haben die Idioten das Spiel doch tatsächlich noch aus der Hand gegeben!"}]'::jsonb, ''),
  ('da-schuali-kaunn-a-mooss-in-an-zug-owilaan', 'Da Schuali kaunn a Mooss in an Zug owilaan!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Schurli kann eine Maß in einem Zug runterleeren!', '[{"kategorie": "wörtlich", "text": "\"Der Schurli kann eine Maß Bier in einem einzigen Zug runterleeren!\"  2. Der Schurli kippt eine Maß in einem Zug runter!  3. Der Schurli büchst ''ne Maß Bier in einem Zug runter, dass man fast applaudieren möcht!"}]'::jsonb, ''),
  ('wea-nochn-pischn-ned-owelossd-kriagd-von-da-heislfrau-a-watschn-und-muass-zwa-euro-schdrof-zoin', 'Wea nochn Pischn ned owelossd, kriagd von da Heislfrau a Watschn und muass zwa Euro Schdrof zoin!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wer nach dem Pischen nicht runterlässt, kriegt von der Häuslfrau eine Watschen und muss zwei Euro Strafe zahlen!', '[{"kategorie": "wörtlich", "text": "\"Wer nach seinem Geschäft nicht die Klospülung betätigt, kriegt von der Häuslfrau eine Watschen und muss zwei Euro Strafe bezahlen!\"  2. Wer sein Geschäft verrichtet und nicht runterlässt, kriegt von der Klofrau eine Watschen und ist um zwei Euro ärmer!  3. Wer nach dem Toilettengang die Spülung vergisst, wird von der Putzkraft abgewatscht und zahlt zudem noch 2 Euro Bußgeld!"}]'::jsonb, ''),
  ('loss-es-saeu-laungsaum-owe-damit-i-da-in-laan-kiiwae-draufbindn-kau', 'Loss es Säu laungsaum owe, damit I da in laan Kiiwä draufbindn kau!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Lass das Seil langsam runter, damit ich dir den leeren Kübel draufbinden kann!', '[{"kategorie": "wörtlich", "text": "\"Lass das Seil langsam runter, damit ich dir den leeren Eimer anbinden kann!\"  2. Lass das Seil vorsichtig nach unten, damit ich den Kübel dran befestigen kann!  3. Fahr das Seil langsam runter, ich bind dir den Kübel dran! ([[owelossn]])"}]'::jsonb, ''),
  ('neemds-des-kastl-do-owa-bevua-si-no-wea-in-schaeaedl-auhaud', 'Neemds des Kastl do owa, bevua si no wea in Schäädl auhaud!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Nehmt das Kastl da runter, bevor sich noch wer den Schädel anhaut!', '[{"kategorie": "wörtlich", "text": "\"Nehmt das Kästchen da runter, bevor noch jemand dagegenläuft!\"  2. Montiert das Kästchen bitte ab, bevor sich einer die Rübe anhaut!  3. Das Kästchen muss runter, bevor noch jemand mit dem Kopf dagegenkracht!"}]'::jsonb, ''),
  ('de-politika-soin-de-schdeian-endlich-owaneema-und-ned-scho-wiida-auffesetzn', 'De Politika soin de Schdeian endlich owaneema und ned scho wiida auffesetzn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Politiker sollen die Steuern endlich runternehmen und nicht schon wieder raufsetzen!', '[{"kategorie": "wörtlich", "text": "\"Die sollen endlich mal die Steuern senken – und nicht ständig erhöhen!\"  2. Die Politik sollte endlich die Steuerlast senken, statt sie immer weiter zu erhöhen!  3. Die Politiker sollen uns endlich a bissl was von der Steuer runternehmen – und nicht ständig draufhaun!"}]'::jsonb, ''),
  ('tuads-des-kastl-a-schdickl-auffesetzn-damit-si-kana-de-bian-aurennd', 'Tuads des Kastl a Schdickl auffesetzn, damit si kana de Bian aurennd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Tut das Kastl ein Stück raufsetzen, damit sich keiner die Birne anrennt!', '[{"kategorie": "wörtlich", "text": "\"Setzt das Kästchen ein Stück weiter rauf, damit sich keiner den Kopf anschlägt!\"  2. Bitte montiert das Kästchen ein Stück höher, damit niemand dagegenläuft!  3. Hängt das Kästchen bitte ein Stück weiter rauf – sonst rennt sich noch wer den Schädel an!"}]'::jsonb, ''),
  ('setz-di-mit-da-dreckign-hoosn-ned-aufs-bett', 'Setz di mit da dreckign Hoosn ned aufs Bett!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Setz dich mit der dreckigen Hose nicht aufs Bett!', '[{"kategorie": "wörtlich", "text": "\"Setz dich nicht mit der schmutzigen Hose aufs Bett!\"  2. Mach doch erst die Hose runter, bevor du dich aufs Bett setzt!  3. Könntest du bitte die Hose ausziehen, bevor du dich aufs Bett setzt?"}]'::jsonb, ''),
  ('na-gee-heast-wiads-boid', 'Na gee heast, wiads boid?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na geh, hör mal, wird''s bald?', '[{"kategorie": "wörtlich", "text": "\"Na komm schon, bist du endlich so weit?\"  2. Verdammt, wie lange brauchst du noch?  3. Ach Gott nochmal, das dauert ja ewig!"}]'::jsonb, 'Na gee, heast!'),
