  ('gee-sei-ned-so', 'Gee, sei ned so!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Geh, sei nicht so!', '[{"kategorie": "wörtlich", "text": "\"Hör auf, sei nicht so!\"  2. Nun mach mal halblang!  3. Lass gut sein!"}]'::jsonb, ''),
