  ('gee-wos-ned-ollas-gibt', 'Gee, wos ned ollas gibt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Geh, was es nicht alles gibt!', '[{"kategorie": "wörtlich", "text": "\"Also wirklich, was es nicht alles gibt!\"  2. Na so was, das ist ja ein Ding!  3. Du meine Güte, das ist ja nicht zu glauben!"}]'::jsonb, ''),
  ('gee-dazoeoe-ma-von-dein-gschbusi', 'Gee, dazöö ma von dein Gschbusi!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Geh, erzähl mir von deinem Gspusi!', '[{"kategorie": "wörtlich", "text": "\"Komm schon, erzähl mir von deiner Liebschaft!\"  2. Na los, erzähl mir von deiner Romanze!  3. Lass hören, wie es mit deiner Affäre läuft!  4. Mach schon, erzähl mir von deinem Schwarm!"}]'::jsonb, ''),
  ('gee-des-howi-jo-gean-gmochd', 'Gee, des howi jo gean gmochd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Geh, das habe ich ja gerne gemacht!', '[{"kategorie": "wörtlich", "text": "\"Nicht der Rede Wert, das habe ich ja gerne gemacht!\"  2. Keine Ursache, das mache ich doch gerne!  3. Schon gut, das war doch selbstverständlich!"}]'::jsonb, ''),
  ('geen-s', 'Geen S''!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Gehen Sie!', '[{"kategorie": "wörtlich, Ausruf des Ermunterung", "text": "\"Na los!\" \"Kommen Sie!\"  \"Machen sie schon!\""}, {"kategorie": "Ausdruck der Ablehnung", "text": "Hören Sie auf!   Lassen Sie es gut sein!"}, {"kategorie": "Höflichkeitsbezeugung", "text": "Nicht der Rede wert!   Keine Ursache!"}, {"kategorie": "Ausruf der Ungläubigkeit", "text": "Na sowas! Du meine Güte! Also wirklich!"}]'::jsonb, 'Geen S'', wos ned ollas gibt!'),
