  ('geen-s-dazoeoen-s-ma-von-eanan-gschbusi', 'Geen S'', dazöön S'' ma von eanan Gschbusi!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Gehen Sie, erzählen Sie mir von Ihrem Gspusi!', '[{"kategorie": "wörtlich", "text": "\"Na los, erzählen Sie mir von Ihrer Liebschaft!\"  2. Raus damit, erzählen Sie mir von Ihrer Romanze!  3. Lassen Sie hören, wie es mit Ihrer Affäre läuft!  4. Machen Sie schon, erzählen Sie mir von Ihrem Schwarm!"}]'::jsonb, ''),
  ('owa-gee', 'Owa gee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Aber geh!', '[{"kategorie": "wörtlich, Ausruf des Erstaunens", "text": "\"Das gibt''s doch nicht!\"  \"Das darf nicht wahr sein!\""}, {"kategorie": "Ausdruck der Ablehnung", "text": "Hör auf!   Lass gut sein!"}, {"kategorie": "Höflichkeitsbezeugung", "text": "Nicht der Rede wert!   Keine Ursache!"}, {"kategorie": "Ausruf der Ungläubigkeit", "text": "Na sowas! Du meine Güte! [[Do legst di nieda!]]"}]'::jsonb, ''),
  ('wiara-wiida-blaadlwaach-haamkumma-is-hods-eam-de-koellaschdiang-owegschdessn', 'Wiara wiida blaadlwaach haamkumma is, hods eam de Köllaschdiang owegschdessn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wie er wieder plattelweich nach Hause gekommen ist, hat sie ihn die Kellerstiege hinuntergestoßen!', '[{"kategorie": "wörtlich", "text": "\"Als er wieder sturzbetrunken nach Hause gekommen ist, hat sie ihn die Kellerstiege hinuntergestoßen!\" 2. Als er wieder sternhagelvoll heimgetorkelt kam, stieß sie ihn die Kellertreppe hinunter!  3. Als er wieder einmal [[vollfett]] nach Hause kam, hat sie ihn kurzerhand die Kellerstiege hinabbefördert!"}]'::jsonb, ''),
  ('bis-mei-oide-a-glaasl-limo-ausbippald-hod-hob-i-locka-scho-fuenf-bia-owegschdessn', 'Bis mei Oide a Glaasl Limo ausbippald hod, hob I locka scho fünf Bia owegschdessn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bis meine Alte ein Glas Limonade ausgepipperlt hat, hab ich locker schon fünf Bier runtergestoßen!', '[{"kategorie": "wörtlich", "text": "\"Bis meine Alte ein Glas Limonade leergenippt hat, hab ich locker schon fünf Bier runtergekippt!\"  2. Bis meine Frau ihre Limo austrinkt, hab ich schon locker fünf Bier weggehauen!  3. Während meine Frau noch an ihrer Limonade nippt, hab ich mein Sechser-Tragerl schon fast leer!"}]'::jsonb, ''),
  ('gee-troog-ma-in-mist-owe', 'Gee, troog ma in Mist owe!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Geh, trag mir den Mist runter!', '[{"kategorie": "wörtlich", "text": "\"Komm schon, trag mir den Mist runter!\"  2. Los jetzt, bring den Müll nach unten!  3. Mach schon, schaff den Müll runter!"}]'::jsonb, ''),
  ('i-loss-mi-sicha-ned-owetroong', 'I loss mi sicha ned owetroong!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich lasse mich sicher nicht runtertragen', '[{"kategorie": "wörtlich", "text": "\"Ich lass mich nicht runtermachen!\"  2. Ich lass mich nicht fertigmachen!  3. Ich lasse mich nicht schlechtmachen!  4. Ich lasse mich nicht kleinmachen!"}]'::jsonb, ''),
  ('den-hods-otrogn', 'Den hods otrogn!', '', '', '', '', 'Den hat es abgetragen!', '[{"kategorie": "", "text": "Der hat eine Schlappe hinnehmen müssen!  2. Den hat es auf die Verliererstraße verschlagen!"}]'::jsonb, ''),
