  ('wem-ofoan-lossn', 'wem ofoan lossn', '', '', '', '', 'jemanden abfahren lassen', '[{"kategorie": "", "text": "jemanden abblitzen lassen"}, {"kategorie": "", "text": "jemandem einen Korb geben"}, {"kategorie": "", "text": "jemanden kalt auflaufen lassen"}, {"kategorie": "", "text": "[[wem]] wos moin"}, {"kategorie": "", "text": "[[wem]] de Guakn geem"}]'::jsonb, ''),
  ('den-hod-a-ofoan-lossn', 'Den hod a ofoan lossn!', '', '', '', '', 'Den hat er abfahren lassen!', '[{"kategorie": "", "text": "Den hat er abblitzen lassen!  2. Den hat er kalt auflaufen lassen!  3. [[Dem]] hat er was gemalt!"}]'::jsonb, ''),
  ('du-wiast-glei-ane-ofaaman', 'Du wiast glei ane ofaaman!', '', '', '', '', 'Du wirst gleich eine abfamen!', '[{"kategorie": "", "text": "Du wirst gleich eine abräumen!\"  2. Du wirst gleich eine Ohrfeige bekommen!"}]'::jsonb, ''),
  ('faeu-oo', 'Fäu oo!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Faul ab!', '[{"kategorie": "", "text": "Verrotte!  2. Hau ab!  3. Verschwinde!  4. [[Schleich]] di!  5. [[Kräull]] ab!  6. [[Gee]] päule!  7. [[Geh]] scheißen!"}]'::jsonb, ''),
  ('wem-heafotzn', 'wem heafotzn', '', '', '', '', 'jemanden herfotzen', '[{"kategorie": "wörtlich", "text": "\"jemandem mit der flachen Hand wiederholt kräftig ins Gesicht schlagen\"  (von \"Fotze\"=\"Ohrfeige\", vom mittelhochdeutschen \"fotze\"=\"dicke Lippe\")"}, {"kategorie": "", "text": "jemanden kräftig ohrfeigen, [[abwatschen]], [[abfotzen]], [[dögeln]]"}, {"kategorie": "", "text": "jemandem eine [[tuschen]], [[picken]], [[paschen]], [[schnalzen]], [[schmieren]], [[reiben]], [[antauchen]]"}]'::jsonb, ''),
